window.BT11={"B1": {"ten": "Bài 1. Dao động điều hòa", "ch": "Chương I. Dao động", "dem": {"I": 9, "II": 2, "III": 0, "TL": 3}, "word": "k11-bt/word/Bai01_Dao_dong_dieu_hoa.docx", "wordDa": "k11-bt/word/Bai01_Dao_dong_dieu_hoa_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Chuyển động nào sau đây <b>không phải</b> là dao động cơ học?</p><figure><img src=\"k11-bt/h/image1.png\" width=\"1374\" height=\"270\" style=\"width:16.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Chuyển động đung đưa của lá cây."], ["B", "Chuyển động của ôtô chạy trên đường."], ["C", "Chuyển động qua lại của con lắc đồng hồ"], ["D", "Chuyển động nhấp nhô của phao trên mặt nước."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Dao động mà trạng thái chuyển động của vật (vị trí và vận tốc) được lặp lại như cũ sau những khoảng thời gian bằng nhau được gọi là</p>", "lc": [["A", "dao động cơ học."], ["B", "dao động tuần hoàn."], ["C", "dao động tự do."], ["D", "sự tự dao động."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Dựa vào hình vẽ, cách nào sau đây có thể tạo ra dao động cho con lắc lò xo và con lắc đơn?</p><figure><img src=\"k11-bt/h/image2.png\" width=\"237\" height=\"372\" style=\"width:2.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Nâng vật lên theo phương thẳng đứng rồi giữ cố định ở vị trí mới."], ["B", "Kéo vật xuống rồi giữ cố định (hình a) hoặc kéo vật sang ngang rồi giữ nguyên (hình b)."], ["C", "Gắn thêm một vật nhỏ vào vật đang treo rồi giữ nguyên vị trí."], ["D", "Kéo vật xuống một đoạn nhỏ theo phương thẳng đứng (hình a) hoặc kéo vật sang ngang một đoạn nhỏ (hình b) rồi thả nhẹ."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Phát biểu nào sau đây <b>sai</b> khi nói về dao động điều hòa?</p>", "lc": [["A", "Dao động điều hòa có li độ của vật là một hàm cosin (hoặc sin) theo thời gian x = Acos(ωt + φ). Trong đó A, ω, φ là các hằng số."], ["B", "Đồ thị li độ - thời gian của một vật dao động điều hòa là một đường hình sin."], ["C", "Dao động điều hòa là dạng dao động tuần hoàn đơn giản nhất; tuy nhiên, không phải mọi dao động tuần hoàn đều là dao động điều hòa."], ["D", "Quỹ đạo chuyển động của vật dao động điều hòa là một đường hình sin."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Phát biểu nào sau đây <b>sai</b> khi nói về các đại lượng trong phương trình li độ x = Acos(ωt + φ) (A &gt; 0, ω &gt; 0) của vật dao động điều hoà</p>", "lc": [["A", "x là li độ dao động."], ["B", "A là biên độ dao động."], ["C", "<span class=\"m\">(\\omega t+\\varphi)</span> là pha ban đầu của dao động."], ["D", "<span class=\"m\">\\varphi</span> là pha ban đầu của dao động."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Phương trình nào sau đây <b>không</b> biểu diễn một dao động điều hòa</p>", "lc": [["A", "x = 3sin5πt (cm)."], ["B", "x = 2tcos5πt (cm)."], ["C", "x = 5cosπt (cm)."], ["D", "x = 4cos (πt -<span class=\"m\">\\dfrac{\\pi}{6})</span> (cm)."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Một con lắc đơn dao động điều hòa với phương trình li độ x = 2cos(2πt + <span class=\"m\">\\dfrac{\\pi}{3}</span>) (cm). Pha ban đầu của dao động là</p>", "lc": [["A", "2 rad."], ["B", "(2πt + <span class=\"m\">\\dfrac{\\pi}{3}</span>) rad."], ["C", "<span class=\"m\">\\dfrac{\\pi}{3}</span> rad."], ["D", "2π rad."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hòa có phương trình li độ x = 5cos(10πt + <span class=\"m\">\\dfrac{\\pi}{3}</span>) (cm). Li độ của chất điểm khi pha dao động bằng π rad là</p>", "lc": [["A", "2,5 cm."], ["B", "-2,5 cm."], ["C", "-5 cm."], ["D", "5 cm."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Pit-tông của một động cơ đốt trong dao động điều hòa trên một đoạn thẳng dài 14 cm và làm cho trục khuỷu của động cơ quay đều. Biên độ dao động của một điểm trên bề mặt pit-tông bằng</p><figure><img src=\"k11-bt/h/image3.png\" width=\"105\" height=\"224\" style=\"width:1.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "56 cm."], ["B", "7 cm."], ["C", "28 cm."], ["D", "14 cm."]], "ds": [], "col": 4, "da": "B", "lg": ""}], "II": [{"than": "<p>Tại nơi có lực ma sát không đáng kể, người ta cho một con lắc đơn dao động với góc lệch nhỏ <span class=\"m\">(\\le</span> 10°). Vị trí của vật xác định bằng một cảm biến khoảng cách kết nối với máy tính. Trên màn hình máy tính hiển thị đồ thị li độ - thời gian. Nhận xét tính đúng hoặc sai của các thông tin sau</p><figure><img src=\"k11-bt/h/image4.png\" width=\"562\" height=\"271\" style=\"width:11.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Dao động của con lắc đơn là dao động điều hòa."], ["b", "Biên độ dao động là 1,0 cm."], ["c", "Tại thời điểm t = 6,0 s vật có li độ x = - 2,0 cm và chuyển động cùng chiều dương."], ["d", "Cứ sau khoảng thời gian 5,0 s, trạng thái dao động của vật lặp lại như cũ."]], "col": 0, "da": "Đ S S S", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hòa với phương trình x = 5cos (10πt +<span class=\"m\">\\dfrac{\\pi}{3})</span> (cm). Nhận xét tính đúng hoặc sai của các phát biểu sau</p>", "lc": [], "ds": [["a", "Pha ban đầu của dao động là <span class=\"m\">\\dfrac{\\pi}{3}</span> rad."], ["b", "Li độ của vật khi pha dao động bằng π (rad) là -0,846 cm."], ["c", "Tại thời điểm ban đầu (t = 0), vật qua vị trí có li độ x = 2,5 cm."], ["d", "Chất điểm này chuyển động trên đoạn thẳng dài 10 cm."]], "col": 0, "da": "Đ S Đ Đ", "lg": ""}], "III": [], "TL": [{"than": "<p>Dao động tự do là dao động của hệ xảy ra sau khi được kích thích ban đầu và tự nó tiếp tục dao động mà không chịu tác dụng của các lực từ bên ngoài.</p><p>Các ví dụ: - Dao động của con lắc lò xo (1), con lắc đơn (2) sau khi kích thích.</p><p>- Dùng búa cao su gõ vào nhánh âm thoa, âm thoa dao động phát ra âm thanh (3).</p><p>- Gảy dây đàn guitar rồi thả ra, dây đàn dao động phát ra âm thanh (4).</p><figure><img src=\"k11-bt/h/image5c0.png\" width=\"870\" height=\"319\" style=\"width:13.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>Trên thực tế, các dao động trên chỉ diễn ra một thời gian rồi dừng lại. Dựa vào kiến thức thực tế, em hãy giải thích vì sao chúng ta không thể duy trì dao động tự do mãi mãi như trong lý thuyết?</p>", "lc": [], "ds": [], "col": 0, "da": "", "lg": "<p><b>Giải thích: (chỉ cần 1 ý)</b></p><p>-Trong thực tế luôn có lực cản của không khí (hoặc lực ma sát).</p><p>-Lực cản/ma sát làm năng lượng của vật bị mất dần nên vật dừng lại.</p>"}, {"than": "<p>Một vật nhỏ dao động điều hòa có đồ thị li độ - thời gian như hình vẽ</p><figure><img src=\"k11-bt/h/image6c0.png\" width=\"786\" height=\"458\" style=\"width:8.4cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Tính độ dịch chuyển của vật từ thời điểm ban đầu (t = 0) đến thời điểm t = 0,5 s.</p><p><b>b)</b> Tính tốc độ trung bình của vật trong khoảng thời gian 0,75 s kể từ lúc bắt đầu dao động.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 20 cm. b) 22,2 cm/s.", "lg": ""}, {"than": "<p>Một vật nhỏ dao động điều hòa có đồ thị li độ - thời gian như hình vẽ</p><figure><img src=\"k11-bt/h/image7.png\" width=\"870\" height=\"357\" style=\"width:10.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Tính số dao động vật thực hiện trong 1,6 s.</p><p><b>b)</b> Kể từ thời điểm t = 0, sau bao nhiêu giây thì vật đi được quãng đường 1,40 cm.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 4 dao động. b) 0,7 s.", "lg": ""}]}, "B2": {"ten": "Bài 2. Mô tả dao động điều hòa", "ch": "Chương I. Dao động", "dem": {"I": 16, "II": 2, "III": 6, "TL": 2}, "word": "k11-bt/word/Bai02_Mo_ta_dao_dong_dieu_hoa.docx", "wordDa": "k11-bt/word/Bai02_Mo_ta_dao_dong_dieu_hoa_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Chọn phát biểu <b>sai</b> khi nói về một chất điểm dao động điều hòa.</p>", "lc": [["A", "Phương trình li độ có dạng x = A cos(ωt + φ)."], ["B", "Quỹ đạo của chất điểm là một đoạn thẳng."], ["C", "Đồ thị li độ - thời gian là một đường hình sin."], ["D", "Pha của dao động biến thiên điều hòa theo thời gian."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Phát biểu nào sau đây là <b>sai</b> khi nói về các đại lượng <b>không phụ thuộc</b> vào thời gian và được dùng để đặc trưng cho dao động điều hòa?</p>", "lc": [["A", "Biên độ dao động."], ["B", "Li độ dao động."], ["C", "Tần số dao động."], ["D", "Tần số góc của dao động."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Độ dịch chuyển của vật từ vị trí cân bằng đến vị trí của vật tại thời điểm t gọi là</p>", "lc": [["A", "li độ."], ["B", "tần số."], ["C", "pha ban đầu."], ["D", "biên độ."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Biên độ của một vật dao động điều hòa là</p>", "lc": [["A", "khoảng cách giữa hai vị trí biên."], ["B", "độ dịch chuyển của vật tính từ vị trí cân bằng."], ["C", "độ lệch của vật so với vị trí cân bằng tại một thời điểm bất kì."], ["D", "độ dịch chuyển cực đại của vật tính từ vị trí cân bằng."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Trong dao động điều hòa, khoảng thời gian để vật thực hiện được một dao động toàn phần gọi là</p>", "lc": [["A", "chu kì."], ["B", "biên độ."], ["C", "tần số."], ["D", "tần số góc."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Trong dao động điều hòa, số dao động toàn phần mà vật thực hiện được trong một đơn vị thời gian gọi là</p>", "lc": [["A", "tần số góc."], ["B", "chu kỳ dao động."], ["C", "pha ban đầu."], ["D", "tần số dao động."]], "ds": [], "col": 4, "da": "D", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hoà thực hiện một dao động toàn phần trong thời gian 0,2 giây. Tần số dao động của chất điểm là</p>", "lc": [["A", "<span class=\"m\">5\\ \\text{Hz}</span>."], ["B", "<span class=\"m\">10\\ \\text{Hz}</span>."], ["C", "<span class=\"m\">20\\ \\text{Hz}</span>."], ["D", "<span class=\"m\">5\\pi\\ \\text{Hz}</span>."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Đại lượng đặc trưng cho tốc độ biến thiên của pha dao động là</p>", "lc": [["A", "pha dao động."], ["B", "chu kì dao động."], ["C", "tần số dao động."], ["D", "tần số góc của dao động."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Một vật dao động điều hòa với tần số <span class=\"m\">f</span>, chu kỳ <span class=\"m\">T</span> và tần số góc <span class=\"m\">\\omega</span>. Biểu thức liên hệ nào sau đây đúng?</p>", "lc": [["A", "<span class=\"m\">T=\\dfrac{\\omega}{2\\pi}</span>"], ["B", "<span class=\"m\">f=\\dfrac{2\\pi}{T}</span>"], ["C", "<span class=\"m\">f=\\dfrac{\\omega}{2\\pi}</span>"], ["D", "<span class=\"m\">\\omega =\\dfrac{2\\pi}{f}</span>"]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Trong hệ SI, đơn vị của tần số góc là</p>", "lc": [["A", "giây (s)."], ["B", "héc (Hz)."], ["C", "radian trên giây (rad/s)."], ["D", "mét (m)."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Vật dao động điều hòa với biên độ, tần số và pha ban đầu lần lượt là A, f, φ. Đại lượng luôn dương trong ba đại lượng trên là</p>", "lc": [["A", "f, φ."], ["B", "A, f."], ["C", "A, f, φ."], ["D", "A, φ."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Cho đồ thị li độ - thời gian của con lắc lò xo như hình bên. Trong các đoạn thời gian được biểu diễn trên trục t, đoạn nào sau đây tương ứng với một chu kỳ dao động?</p><figure><img src=\"k11-bt/h/image8.png\" width=\"661\" height=\"388\" style=\"width:9.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "đoạn FH."], ["B", "đoạn HQ."], ["C", "đoạn FQ."], ["D", "đoạn OH."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Đại lượng nào dưới đây đặc trưng cho độ lệch về thời gian giữa hai dao động điều hoà cùng chu kì?</p>", "lc": [["A", "Li độ."], ["B", "Pha."], ["C", "Pha ban đầu."], ["D", "Độ lệch pha."]], "ds": [], "col": 4, "da": "D", "lg": ""}, {"than": "<p>Cho hai dao động điều hòa cùng tần số <span class=\"m\">x_{1}</span> = <span class=\"m\">A_{1}</span> cos(ωt + <span class=\"m\">\\varphi_{1}</span>) và <span class=\"m\">x_{2}</span> = <span class=\"m\">A_{2}</span> cos(ωt + <span class=\"m\">\\varphi_{2}</span>). Độ lệch pha Δφ của dao động <span class=\"m\">x_{2}</span> so với dao động <span class=\"m\">x_{1}</span> là</p>", "lc": [["A", "Δφ = <span class=\"m\">\\dfrac{\\varphi_{1}+\\varphi_{2}}{2}</span>."], ["B", "Δφ = <span class=\"m\">\\varphi_{1}</span> + <span class=\"m\">\\varphi_{2}</span>."], ["C", "Δφ = <span class=\"m\">\\varphi_{2}</span> - <span class=\"m\">\\varphi_{1}</span>."], ["D", "Δφ = <span class=\"m\">\\varphi_{1}</span>.<span class=\"m\">\\varphi_{2}</span>."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Hai dao động điều hoà cùng phương, cùng tần số có phương trình dao động là <span class=\"m\">x_{1}</span> = 4cos(10πt +<span class=\"m\">\\dfrac{\\pi}{2}</span>) cm và <span class=\"m\">x_{2}</span> = 4<span class=\"m\">\\sqrt{2}</span> cos(10πt - <span class=\"m\">\\dfrac{\\pi}{6}</span>) cm. So với dao động thứ nhất thì dao động thứ hai</p>", "lc": [["A", "trễ pha hơn <span class=\"m\">\\dfrac{\\pi}{3}</span> rad."], ["B", "sớm pha hơn <span class=\"m\">\\dfrac{\\pi}{6}</span> rad."], ["C", "trễ pha hơn <span class=\"m\">\\dfrac{2\\pi}{3}</span> rad."], ["D", "sớm pha hơn <span class=\"m\">\\dfrac{2\\pi}{3}</span> rad."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Gọi <span class=\"m\">T</span> là chu kì dao động, <span class=\"m\">\\Delta t</span> là khoảng thời gian ngắn nhất để hai dao động có cùng trạng thái. Độ lớn độ lệch pha <span class=\"m\">\\Delta \\varphi</span> giữa hai dao động được tính theo công thức</p>", "lc": [["A", "<span class=\"m\">\\Delta \\varphi =\\pi \\dfrac{\\Delta t}{T}</span>."], ["B", "<span class=\"m\">\\Delta \\varphi =2\\pi \\dfrac{T}{\\Delta t}</span>."], ["C", "<span class=\"m\">\\Delta \\varphi =4\\pi \\dfrac{\\Delta t}{T}</span>."], ["D", "<span class=\"m\">\\Delta \\varphi =2\\pi \\dfrac{\\Delta t}{T}</span>."]], "ds": [], "col": 2, "da": "D", "lg": ""}], "II": [{"than": "<p>Hai chất điểm (1) và (2) dao động điều hòa có cùng tần số và có đồ thị li độ - thời gian như hình vẽ.</p><figure><img src=\"k11-bt/h/image9.jpg\" width=\"422\" height=\"215\" style=\"width:6.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Vật (1) đạt li độ cực tiểu trước vật (2)."], ["b", "Chu kì dao động của vật (1) bằng 2,4 s."], ["c", "Độ lớn độ lệch pha của hai dao động là <span class=\"m\">\\dfrac{\\pi}{6}</span> rad."], ["d", "Phương trình dao động của vật (1) là <span class=\"m\">x_{1} = \\sqrt{3}.\\cos \\left(\\dfrac{5\\pi}{6} t-\\dfrac{\\pi}{2}\\right)</span> cm."]], "col": 0, "da": "S Đ S S", "lg": ""}, {"than": "<p>Một vật dao động điều hoà với biên độ <span class=\"m\">6\\ \\text{cm}</span>, tần số góc <span class=\"m\">\\omega =10\\pi\\ \\text{rad}/s</span>. Chọn gốc tọa độ <span class=\"m\">O</span> trùng với vị trí cân bằng của vật, gốc thời gian lúc vật bắt đầu chuyển động từ vị trí biên dương.</p>", "lc": [], "ds": [["a", "Quỹ đạo chuyển động của vật là một đường hình sin."], ["b", "Ngay sau thời điểm t = 0, vật chuyển động cùng chiều dương."], ["c", "Phương trình dao động của vật là <span class=\"m\">x=6\\cos \\left(10\\pi t-\\dfrac{\\pi}{6}\\right)</span> cm."], ["d", "Cho π = 3,14 thì độ lớn của độ lệch pha dao động tại hai thời điểm <span class=\"m\">t_{1}</span> = 0 và <span class=\"m\">t_{2}</span> = 0,05s là 1,59 rad."]], "col": 0, "da": "S S S Đ", "lg": ""}], "III": [{"than": "<p>Một chất điểm dao động điều hòa với phương trình li độ x = 2cos(2πt + <span class=\"m\">\\dfrac{\\pi}{2})</span> (x tính bằng cm, t tính bằng s). Tại thời điểm t = 0,25 s, chất điểm có li độ bằng bao nhiêu centimet (cm)?</p>", "lc": [], "ds": [], "col": 0, "da": "-2", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hoà trong thời gian 1 phút vật thực hiện được 30 dao động. Chu kì dao động của vật là bao nhiêu giây (s)?</p>", "lc": [], "ds": [], "col": 0, "da": "2", "lg": ""}, {"than": "<p>Một vật dao động điều hòa theo phương trình x = 4cos(<span class=\"m\">4\\pi t</span> - <span class=\"m\">\\dfrac{2\\pi}{3}</span>) cm (t tính bằng giây). Độ dịch chuyển sau <span class=\"m\">0{,}125</span> giây kể từ thời điểm ban đầu là bao nhiêu centimet (cm)? (kết quả làm tròn đến chữ số hàng phần trăm)</p>", "lc": [], "ds": [], "col": 0, "da": "5,46", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên đoạn thẳng MN = 20 cm như hình bên. Chọn gốc tọa độ O của trục ox trùng với vị trí cân bằng. Biết trong khoảng thời gian 10 s, vật thực hiện được 20 dao động toàn phần. Quãng đường vật đi được trong khoảng thời gian 2 s là bao nhiêu mét (m)?</p><figure><img src=\"k11-bt/h/image10c0.png\" width=\"495\" height=\"83\" style=\"width:9.0cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "1,6", "lg": ""}, {"than": "<p>Độ lớn độ lệch pha của hai dao động điều hòa cùng tần số có đồ thị li độ - thời gian như hình vẽ bên là bao nhiêu radian (rad)? (kết quả làm tròn đến chữ số hàng phần trăm)</p><figure><img src=\"k11-bt/h/image11.png\" width=\"752\" height=\"383\" style=\"width:8.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "0,79", "lg": ""}, {"than": "<p>Hình bên là đồ thị li độ x theo thời gian t của một vật dao động điều hòa trên trục Ox. Độ dịch chuyển của vật từ thời điểm <span class=\"m\">t_{1}</span> = 1,0 s đến <span class=\"m\">t_{2}</span> = 2,0 s là bao nhiêu cm? (kết quả làm tròn đến chữ số hàng đơn vị)</p><figure><img src=\"k11-bt/h/image12c0.png\" width=\"361\" height=\"269\" style=\"width:7.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "-40", "lg": ""}], "TL": [{"than": "<p>Pit-tông bên trong động cơ đốt trong dao động lên và xuống khi động cơ hoạt động. Dao động này được coi là dao động điều hòa với phương trình li độ x = 4cos(4πt) (x tính bằng cm, t tính bằng s).</p><p><b>a)</b> Tính pha dao động của pit-tông tại thời điểm 0,5 s.</p><p><b>b)</b> Tính tốc độ trung bình của pit-tông trong khoảng thời gian 6,0 giây (kể từ lúc t = 0).</p>", "lc": [], "ds": [], "col": 0, "da": "a) π/2 rad. b) 32 cm/s.", "lg": ""}, {"than": "<p>Thực hiện thí nghiệm với thiết bị ghi đồ thị dao động điều hoà của một con lắc lò xo được kết quả như hình vẽ bên. Biết quả nặng có khối lượngS 100g, lò xo nhẹ có độ cứng k = 100N/m và chu kỳ dao động tự do của con lắc lò xo tính bằng công thức T = 2π<span class=\"m\">\\sqrt{\\dfrac{m}{k}}</span>. Lấy π <span class=\"m\">\\approx \\sqrt{10}</span>.</p><figure><img src=\"k11-bt/h/image13.png\" width=\"1338\" height=\"372\" style=\"width:16.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Tính tần số góc của dao động.</p><p><b>b)</b> Xác định pha của dao động tại thời điểm t = <span class=\"m\">\\dfrac{1}{30}</span> s.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 10π rad/s. b) <span class=\"m\">\\dfrac{4\\pi}{3}</span> rad.", "lg": ""}]}, "B3": {"ten": "Bài 3. Vận tốc, gia tốc trong dao động điều hòa", "ch": "Chương I. Dao động", "dem": {"I": 10, "II": 2, "III": 6, "TL": 3}, "word": "k11-bt/word/Bai03_Van_toc_gia_toc.docx", "wordDa": "k11-bt/word/Bai03_Van_toc_gia_toc_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Một vật dao động điều hòa theo phương trình <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span>. Phương trình vận tốc của vật là</p>", "lc": [["A", "<span class=\"m\">v=\\omega^{2}A\\sin \\left(\\omega t+\\varphi \\right)</span>."], ["B", "<span class=\"m\">v=-\\omega A\\cos \\left(\\omega t+\\varphi \\right)</span>."], ["C", "<span class=\"m\">v=\\omega A\\cos \\left(\\omega t+\\varphi \\right)</span>."], ["D", "<span class=\"m\">v=-\\omega A\\sin \\left(\\omega t+\\varphi \\right)</span>."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Đồ thị biểu diễn sự biến thiên của vận tốc theo thời gian trong dao động điều hoà có dạng</p>", "lc": [["A", "đường thẳng."], ["B", "đoạn thẳng."], ["C", "đường hình sin."], ["D", "đường elip."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Một vật dao động điều hòa có có phương trình li độ là <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span> với A &gt; 0. Vận tốc cực đại của dao động là</p>", "lc": [["A", "<span class=\"m\">v_{\\max}=\\omega^{2}A</span>."], ["B", "<span class=\"m\">v_{\\max}=-\\omega^{2}A</span>."], ["C", "<span class=\"m\">v_{\\max}=\\omega A</span>."], ["D", "<span class=\"m\">v_{\\max}=-\\omega A</span>."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Một vật dao động điều hòa theo phương trình <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span>. Phương trình gia tốc của vật là</p>", "lc": [["A", "<span class=\"m\">a=-\\omega^{2}A\\sin \\left(\\omega t+\\varphi \\right)</span>."], ["B", "<span class=\"m\">a=-\\omega^{2}A\\cos \\left(\\omega t+\\varphi \\right)</span>."], ["C", "<span class=\"m\">a=\\omega A^{2}\\cos \\left(\\omega t+\\varphi \\right)</span>."], ["D", "<span class=\"m\">a=\\omega^{2}A\\sin \\left(\\omega t+\\varphi \\right)</span>."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Một vật dao động điều hòa có có phương trình li độ là <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span> với A &gt; 0. Giá trị cực đại của gia tốc là</p>", "lc": [["A", "<span class=\"m\">a_{\\max}=\\omega^{2}A</span>."], ["B", "<span class=\"m\">a_{\\max}=-\\omega^{2}A</span>."], ["C", "<span class=\"m\">a_{\\max}=\\omega A</span>."], ["D", "<span class=\"m\">a_{\\max}=-\\omega A</span>."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Một vật nhỏ dao động điều hòa trên trục Ox với tần số góc ω. Ở li độ x, vật có gia tốc là</p>", "lc": [["A", "a = -ω²x."], ["B", "a = ω²x."], ["C", "a = -ωx²."], ["D", "a = -ωx."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Đồ thị biểu diễn sự biến thiên của gia tốc theo li độ trong dao động điều hoà có dạng</p>", "lc": [["A", "đường thẳng."], ["B", "đoạn thẳng."], ["C", "đường hình sin."], ["D", "đường elip."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Trong dao động điều hòa, vận tốc biến thiên điều hòa và</p>", "lc": [["A", "cùng pha với li độ."], ["B", "trễ pha <span class=\"m\">\\dfrac{\\pi}{2}</span> so với li độ."], ["C", "sớm pha <span class=\"m\">\\dfrac{\\pi}{2}</span> so với li độ."], ["D", "ngược pha với li độ."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Trong dao động điều hòa, vận tốc biến thiên điều hòa và</p>", "lc": [["A", "cùng pha với gia tốc."], ["B", "trễ pha <span class=\"m\">\\dfrac{\\pi}{2}</span> so với gia tốc."], ["C", "sớm pha <span class=\"m\">\\dfrac{\\pi}{2}</span> so với gia tốc."], ["D", "ngược pha với gia tốc."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên trục Ox quanh vị trí cân bằng O. Vectơ gia tốc của vật</p>", "lc": [["A", "luôn hướng ra xa vị trí cân bằng."], ["B", "có độ lớn tỷ lệ nghịch với độ lớn li độ của vật."], ["C", "luôn hướng về vị trí cân bằng."], ["D", "có độ lớn tỷ lệ thuận với độ lớn vận tốc của vật."]], "ds": [], "col": 1, "da": "C", "lg": ""}], "II": [{"than": "<p>Cho đồ thị biểu diễn vận tốc v theo thời gian t của một vật dao động điều hòa như hình. Các phát biểu sau đây đúng hay sai?</p><figure><img src=\"k11-bt/h/image31c0.png\" width=\"630\" height=\"271\" style=\"width:7.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Vận tốc biến đổi cùng pha với li độ."], ["b", "Theo đồ thị, vận tốc của vật có độ lớn cực đại lần đầu tiên ở thời điểm t = 0,4 s."], ["c", "Tại thời điểm t = 0,1 s, vật ở vị trí cân bằng."], ["d", "Biên độ dao động của vật là 20 cm."]], "col": 0, "da": "S Đ Đ S", "lg": ""}, {"than": "<p>Cho đồ thị biểu diễn gia tốc a theo thời gian t của một vật dao động điều hòa như hình. Trong đó A là biên độ dao động, ω là tần số góc. Các phát biểu sau đây đúng hay sai?</p><figure><img src=\"k11-bt/h/image32.png\" width=\"437\" height=\"288\" style=\"width:6.0cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><figure><img src=\"k11-bt/h/image33c0.png\" width=\"1024\" height=\"708\" style=\"width:6.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Đồ thị biểu diễn sự biến thiên của gia tốc theo thời gian trong dao động điều hòa có dạng hình sin."], ["b", "Li độ, vận tốc và gia tốc của vật dao động điều hòa là những đại lượng biến đổi theo hàm cosin (hoặc sin) theo thời gian và có cùng tần số góc."], ["c", "Gia tốc của dao động có độ lớn cực tiểu khi vật ở vị trí biên dương."], ["d", "Đồ thị biểu diễn li độ x theo thời gian t tương ứng dao động trên được biểu diễn như hình bên dưới."]], "col": 0, "da": "Đ Đ S S", "lg": ""}], "III": [{"than": "<p>Một vật dao động điều hòa trên trục Ox. Quan sát đồ thị vận tốc – thời gian của một vật dao động điều hòa dưới đây. Tính gia tốc cực đại của vật theo đơn vị cm/s² (Kết quả làm tròn đến hàng đơn vị)</p><figure><img src=\"k11-bt/h/image34.png\" width=\"629\" height=\"307\" style=\"width:7.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "40", "lg": ""}, {"than": "<p>Một vật dao động điều hòa với phương trình x = 4cos(2πt) (x tính bằng cm, t tính bằng s). Vận tốc cực tiểu của vật là y.π (cm/s). Tìm y.</p>", "lc": [], "ds": [], "col": 0, "da": "-3", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hòa trên trục Ox với chu kì T. Vị trí cân bằng của chất điểm trùng với gốc tọa độ. Khoảng thời gian ngắn nhất để chất điểm đi từ vị trí vận tốc cực đại đến vị trí vận tốc cực tiểu là <span class=\"m\">\\dfrac{T}{a}</span>. Hãy tìm a.</p>", "lc": [], "ds": [], "col": 0, "da": "2", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên trục Ox. Hình bên là đồ thị biểu diễn sự phụ thuộc của vận tốc v vào thời gian t. Khi li độ của vật là 4 cm thì gia tốc của vật bằng bao nhiêu cm/s²? Lấy π = 3,14. Kết quả làm tròn đến chữ số hàng phần mười.</p><figure><img src=\"k11-bt/h/image36.png\" width=\"731\" height=\"388\" style=\"width:6.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "-9,9", "lg": ""}, {"than": "<p>Một chất điểm dao động điều hòa trên trục Ox với chu kì T. Vị trí cân bằng của chất điểm trùng với gốc tọa độ. Khoảng thời gian ngắn nhất để chất điểm đi từ vị trí gia tốc có độ lớn cực đại đến vị trí gia tốc có độ lớn cực tiểu là <span class=\"m\">\\dfrac{T}{b}</span>. Hãy tìm b.</p>", "lc": [], "ds": [], "col": 0, "da": "4", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên trục Ox. Quan sát đồ thị gia tốc – thời gian của một vật dao động điều hòa dưới đây. Sau bao nhiêu giây kể từ thời điểm t = 0, vectơ gia tốc đổi chiều lần đầu tiên?</p><figure><img src=\"k11-bt/h/image38.png\" width=\"612\" height=\"388\" style=\"width:6.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "1", "lg": ""}], "TL": [{"than": "<p>Trong kĩ thuật cơ khí, pit-tông của một động cơ đốt trong khi hoạt động sẽ tạo ra những dao động được xem gần đúng là dao động điều hòa với phương trình <span class=\"m\">x=2\\cos (180\\pi t)</span> mm.</p><p>a) Viết phương trình vận tốc của một điểm trên pit-tông.</p><p>b) Tại sao không thể nói \"Pit-tông chuyển động nhanh dần đều từ điểm biên về vị trí cân bằng\"?</p>", "lc": [], "ds": [], "col": 0, "da": "", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên trục Ox. Hình bên là đồ thị biểu diễn sự phụ thuộc của vận tốc v vào thời gian t.</p><figure><img src=\"k11-bt/h/image40c0.png\" width=\"803\" height=\"441\" style=\"width:7.4cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>a) Tính chu kì dao động của vật.</p><p>b) Tính gia tốc của vật khi vật có li độ là -4 cm.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 4/3 s; b) 6π cm/s².", "lg": ""}, {"than": "<p>Một con lắc lò xo dao động điều hòa có đồ thị biểu diễn đồ thị gia tốc theo li độ như hình.</p><figure><img src=\"k11-bt/h/image41.png\" width=\"927\" height=\"508\" style=\"width:9.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>a) Tính tần số góc của con lắc đó.</p><p>b) Chọn mốc thời gian lúc con lắc tại vị trí cân bằng theo chiều dương. Hãy viết phương trình vận tốc theo thời gian của con lắc trên.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 10 rad/s", "lg": "<p><b>b)</b> <span class=\"m\">x=-0{,}4\\sin \\left(5t-\\dfrac{\\pi}{2}\\right)</span> m/s.</p>"}]}, "B4": {"ten": "Bài 4. Bài tập về dao động điều hòa", "ch": "Chương I. Dao động", "dem": {"I": 5, "II": 1, "III": 2, "TL": 0}, "word": "k11-bt/word/Bai04_Bai_tap_dao_dong_dieu_hoa.docx", "wordDa": "k11-bt/word/Bai04_Bai_tap_dao_dong_dieu_hoa_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Trong dao động điều hòa, li độ, vận tốc và gia tốc biến thiên điều hòa theo thời gian và có cùng</p>", "lc": [["A", "biên độ."], ["B", "tần số."], ["C", "pha ban đầu."], ["D", "Pha dao động."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Hình vẽ thể hiện đồ thị li độ - thời gian của ba vật 1, 2 và 3 khác nhau đang thực hiện dao động điều hòa. Gọi <span class=\"m\">f_{1}</span>, <span class=\"m\">f_{2}</span> và <span class=\"m\">f_{3}</span> là tần số dao động của 3 vật thì</p><figure><img src=\"k11-bt/h/image43c0.png\" width=\"591\" height=\"258\" style=\"width:7.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "<span class=\"m\">f_{1}</span> = <span class=\"m\">f_{2}</span> = <span class=\"m\">f_{3}</span>."], ["B", "<span class=\"m\">f_{1}</span> &gt; <span class=\"m\">f_{2}</span> &gt;<span class=\"m\">f_{3}</span>."], ["C", "<span class=\"m\">f_{1}</span> = <span class=\"m\">f_{2}</span> &lt; <span class=\"m\">f_{3}</span>."], ["D", "<span class=\"m\">f_{1}</span> &lt; <span class=\"m\">f_{2}</span> &lt; <span class=\"m\">f_{3}</span>."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Một vật dao động điều hòa theo một trục cố định. Phát biểu nào dưới đây là <b>không</b> chính xác?</p>", "lc": [["A", "Quãng đường vật đi được trong một chu kì dao động bằng 4 lần biên độ."], ["B", "Đồ thị li độ theo thời gian của vật là một đường hình sin."], ["C", "Chiều dài quỹ đạo chuyển động của vật bằng 2 lần biên độ."], ["D", "Quỹ đạo chuyển động của vật là một đường hình sin."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Xét một vật đang thực hiện dao động điều hòa. Khi vật thực hiện một dao động tương ứng với pha dao động sẽ thay đổi một lượng</p>", "lc": [["A", "5π rad."], ["B", "π rad."], ["C", "2π rad."], ["D", "3π rad."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Một vật dao động điều hòa trên trục Ox quanh vị trí cân bằng O với biên độ A &gt; 0, tần số góc ω. Chọn mốc thời gian là lúc vật có vận tốc cực đại. Đồ thị biểu biễn sự phụ thuộc của li độ theo thời gian được biểu diễn như hình</p><figure><img src=\"k11-bt/h/image44c0.png\" width=\"1560\" height=\"387\" style=\"width:16.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hình 1."], ["B", "Hình 2."], ["C", "Hình 4."], ["D", "Hình 3."]], "ds": [], "col": 4, "da": "A", "lg": ""}], "II": [{"than": "<p>Một vật dao động điều hòa dọc theo trục Ox, quanh điểm gốc O có đồ thị biểu diễn sự phụ thuộc li độ, vận tốc, gia tốc theo thời gian như hình.</p><figure><img src=\"k11-bt/h/image45.png\" width=\"1024\" height=\"314\" style=\"width:15.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>Các phát biểu sau đây đúng hay sai?</p>", "lc": [], "ds": [["a", "Trong dao động điều hòa, li độ, vận tốc và gia tốc biến thiên điều hòa theo thời gian và có cùng pha ban đầu."], ["b", "Vận tốc của vật dao động ngược pha so với li độ."], ["c", "Gia tốc có độ lớn tỉ lệ với độ lớn của li độ."], ["d", "Các đường biểu diễn li độ, vận tốc, gia tốc lần lượt là (3), (2), (1)."]], "col": 0, "da": "S S Đ S", "lg": ""}], "III": [{"than": "<p>Hai dao động điều hòa có đồ thị li độ - thời gian như hình vẽ. Gọi <span class=\"m\">T_{1}</span> và <span class=\"m\">T_{2}</span> là chu kì dao động của dao động (1) và dao động (2) thì <span class=\"m\">T_{2}</span> = n<span class=\"m\">T_{1}</span>. Hãy tìm n.</p><figure><img src=\"k11-bt/h/image46.png\" width=\"584\" height=\"303\" style=\"width:6.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "2", "lg": ""}, {"than": "<p>Khi ca sĩ hát, dây thanh quản của người ca sĩ sẽ dao động với tần số bằng tần số của âm do người đó phát ra. Giả sử người ca sĩ hát tone nhạc “Si giáng trưởng” có tần số khoảng 466 Hz thì trong 2 s dây thanh quản của người đó thực hiện được số dao động là bao nhiêu?</p>", "lc": [], "ds": [], "col": 0, "da": "932", "lg": ""}], "TL": []}, "B5": {"ten": "Bài 5. Động năng. Thế năng. Sự chuyển hóa năng lượng trong dao động điều hòa", "ch": "Chương I. Dao động", "dem": {"I": 14, "II": 2, "III": 4, "TL": 0}, "word": "k11-bt/word/Bai05_Dong_nang_the_nang.docx", "wordDa": "k11-bt/word/Bai05_Dong_nang_the_nang_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Một chất điểm có khối lượng <span class=\"m\">m</span>, dao động điều hòa quanh vị trí cần bằng <span class=\"m\">O</span> với tần số góc <span class=\"m\">\\omega</span>, biên độ <span class=\"m\">A</span>. Khi vận tốc của chất điểm là <span class=\"m\">v</span> thì động năng của chất điểm <span class=\"m\">W_{\\text{đ}}</span> tính bằng biểu thức</p>", "lc": [["A", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\omega^{2}A^{2}</span>."], ["B", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\omega v^{2}</span>."], ["C", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}mv^{2}</span>."], ["D", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\omega^{2}v^{2}</span>."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Một chất điểm có khối lượng <span class=\"m\">m</span>, dao động điều hòa quanh vị trí cần bằng <span class=\"m\">O</span>. Phương trình li độ có dạng <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span>, <span class=\"m\">t</span> tính theo đơn vị giây. Lấy gốc thế năng tại <span class=\"m\">O</span>. Biểu thức tính thế năng <span class=\"m\">W_{\\text{t}}</span> là</p>", "lc": [["A", "<span class=\"m\">W_{\\text{t}}=\\dfrac{1}{2}m\\omega A^{2}\\sin^{2}\\left(\\omega t+\\varphi \\right)</span>."], ["B", "<span class=\"m\">W_{\\text{t}}=\\dfrac{1}{2}m\\omega A^{2}\\cos^{2}\\left(\\omega t+\\varphi \\right)</span>."], ["C", "<span class=\"m\">W_{\\text{t}}=\\dfrac{1}{2}m\\omega^{2}A^{2}\\sin^{2}\\left(\\omega t+\\varphi \\right)</span>."], ["D", "<span class=\"m\">W_{\\text{t}}=\\dfrac{1}{2}m\\omega^{2}A^{2}\\cos^{2}\\left(\\omega t+\\varphi \\right)</span>."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Một chất điểm có khối lượng <span class=\"m\">m</span>, dao động điều hòa quanh vị trí cần bằng <span class=\"m\">O</span> với tần số góc <span class=\"m\">\\omega</span>, biên độ <span class=\"m\">A</span>. Lấy gốc thế năng tại <span class=\"m\">O</span>. Cơ năng <span class=\"m\">W</span> tính bằng biểu thức</p>", "lc": [["A", "<span class=\"m\">W=\\dfrac{1}{2}m\\omega A^{2}</span>."], ["B", "<span class=\"m\">W=\\dfrac{1}{2}m\\omega^{2}A^{2}</span>."], ["C", "<span class=\"m\">W=\\dfrac{1}{2}m\\omega^{2}A</span>."], ["D", "<span class=\"m\">W=\\dfrac{1}{2}m\\omega A</span>."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Một chất điểm có khối lượng <span class=\"m\">m</span>, dao động điều hòa quanh vị trí cân bằng <span class=\"m\">O</span> với tần số góc <span class=\"m\">\\omega</span>.Lấy gốc thế năng tại <span class=\"m\">O</span>. Khi li độ là <span class=\"m\">x</span> thì vận tốc là <span class=\"m\">v</span>. Động năng <span class=\"m\">W_{\\text{đ}}</span> tính bằng biểu thức</p>", "lc": [["A", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\omega^{2}\\left(A^{2}+x^{2}\\right)</span>."], ["B", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\left(\\omega^{2}A^{2}+x^{2}\\right)</span>."], ["C", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\omega^{2}\\left(A^{2}-x^{2}\\right)</span>."], ["D", "<span class=\"m\">W_{\\text{đ}}=\\dfrac{1}{2}m\\left(\\omega^{2}A^{2}-x^{2}\\right)</span>."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Cơ năng của một vật dao động điều hòa tỉ lệ thuận với</p>", "lc": [["A", "li độ dao động."], ["B", "biên độ dao động."], ["C", "bình phương biên độ dao động."], ["D", "tần số dao động."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Chọn câu <b>sai</b>. Một vật dao động điều hòa có chu kì dao động là T. Năng lượng của một vật dao động điều hòa</p>", "lc": [["A", "luôn luôn là một hằng số."], ["B", "bằng động năng của vật khi qua vị trí cân bằng."], ["C", "bằng thế năng của vật khi qua vị trí cân biên."], ["D", "biến thiên tuần hoàn theo thời gian với chu kì T."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Một chất điểm có khối lượng m, dao động điều hòa quanh vị trí cần bằng O với chu kì T, biên độ A. Động năng của vật biến đổi theo thời gian</p><figure><img src=\"k11-bt/h/image88.png\" width=\"676\" height=\"376\" style=\"width:7.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "tuần hoàn với chu kỳ T."], ["B", "Điều hòa với chu kỳ <span class=\"m\">\\dfrac{T}{2}</span>."], ["C", "không đổi."], ["D", "tuần hoàn với chu kỳ <span class=\"m\">\\dfrac{T}{2}</span>."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Một vật dao động điều hoà, cơ năng toàn phần có giá trị là W thì</p>", "lc": [["A", "Tại vị trí biên: động năng bằng W."], ["B", "Tại vị trí cân bằng: động năng bằng W."], ["C", "Tại vị trí bất kì: thế năng lớn hơn W."], ["D", "Tại vị trí bất kì: động năng lớn hơn W."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Cho một vật dao động điều hòa với biên độ A dọc theo trục Ox và quanh gốc tọa độ O. Một đại lượng Y nào đó của vật phụ thuộc vào li độ x của vật theo đồ thị có dạng một phần của đường parabol như hình vẽ bên. Đại lượng Y là</p><figure><img src=\"k11-bt/h/image90c0.png\" width=\"211\" height=\"163\" style=\"width:4.0cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "vận tốc của vật."], ["B", "thế năng của vật."], ["C", "động năng của vật."], ["D", "gia tốc của vật."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Cho một vật dao động điều hòa với biên độ A dọc theo trục Ox và quanh gốc tọa độ O có đồ thị biểu diễn sự phụ thuộc động năng theo li độ như hình bên. Khi vật đi từ li độ x = 3 cm đến vị trí biên dương</p><figure><img src=\"k11-bt/h/image91.png\" width=\"691\" height=\"413\" style=\"width:7.0cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "thế năng của vật chuyển hóa thành cơ năng."], ["B", "cơ năng của vật chuyển hóa thành thế năng."], ["C", "động năng của vật chuyển hóa thành thế năng."], ["D", "thế năng của vật chuyển hóa thành động năng."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Cho một vật dao động điều hòa với biên độ A dọc theo trục Ox và quanh gốc tọa độ O có đồ thị biểu diễn sự phụ thuộc li độ theo thời gian như hình bên.</p><figure><img src=\"k11-bt/h/image92.png\" width=\"598\" height=\"432\" style=\"width:7.4cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Tại thời điểm ban đầu thế năng cực đại."], ["B", "Từ <span class=\"m\">\\dfrac{T}{4}</span> đến thời điểm <span class=\"m\">\\dfrac{3T}{4}</span> thế năng tăng từ 0 đến cực đại."], ["C", "Động năng tại thời điểm <span class=\"m\">\\dfrac{T}{4}</span> bằng thế năng tại thời điểm <span class=\"m\">\\dfrac{T}{2}</span>."], ["D", "Từ <span class=\"m\">\\dfrac{T}{2}</span> đến thời điểm <span class=\"m\">\\dfrac{3T}{4}</span> thế năng giảm từ cực đại về 0."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Cho một vật dao động điều hòa với biên độ A dọc theo trục Ox và quanh gốc tọa độ O có đồ thị biểu diễn sự phụ thuộc vận tốc theo thời gian như hình bên.</p><figure><img src=\"k11-bt/h/image93.png\" width=\"626\" height=\"369\" style=\"width:7.2cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Tại thời điểm ban đầu thế năng cực đại."], ["B", "Trong 0,6 s đầu tiên, động năng chuyển hóa thành thế năng."], ["C", "Trong 1,2 s đầu tiên, cơ năng không đổi."], ["D", "Trong một chu kì dao động của vật, thế năng cực tiểu hai lần."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Chọn phát biểu đúng về sự chuyển hóa năng lượng trong dao động điều hòa.</p>", "lc": [["A", "Thế năng cực đại khi vật ở vị trí cân bằng."], ["B", "Thế năng bằng không khi vật ở biên."], ["C", "Động năng bằng không khi vật ở vị trí cân bằng."], ["D", "Động năng cực đại khi vật ở vị trí cân bằng."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Một vật dao động điều hòa dọc theo trục Ox và xung quanh vị trí cân bằng O. Đồ thị biểu diễn sự thay đổi của một đại lượng Y nào đó theo thời gian trong dao động của vật có dạng như hình vẽ. Đại lượng Y có thể là</p><figure><img src=\"k11-bt/h/image94.png\" width=\"552\" height=\"308\" style=\"width:5.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "thế năng của vật."], ["B", "gia tốc của vật."], ["C", "cơ năng của vật."], ["D", "vận tốc của vật."]], "ds": [], "col": 4, "da": "A", "lg": ""}], "II": [{"than": "<p>Một con lắc lò xo gồm một vật nhỏ khối lượng m và lò xo có độ cứng k. Con lắc dao động điều hòa chu kì T có đồ thị biểu diễn sự phụ thuộc của thế năng theo thời gian như hình. Các phát biểu sau đây đúng hay sai?</p><figure><img src=\"k11-bt/h/image95.png\" width=\"636\" height=\"429\" style=\"width:7.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Tại thời điểm ban đầu thế năng cực đại, sau thời gian <span class=\"m\">\\dfrac{T}{4}</span> thế năng bằng không."], ["b", "Thế năng của vật biến đổi tuần hoàn theo thời gian với chu kì T."], ["c", "Khi vật dao động điều hòa di chuyển từ vị trí cân bằng ra biên thì động năng giảm và thế năng tăng"], ["d", "Chu kì dao động T của con lắc lò xo không phụ thuộc vào khối lượng vật nhỏ."]], "col": 0, "da": "Đ S Đ S", "lg": ""}, {"than": "<p>Một con lắc đơn với góc lệch nhỏ (α ≤ 10°) dao động điều hòa có chiều dài sợi dây l, gia tốc trọng trường g, chu kì <span class=\"m\">T=2\\pi \\sqrt{\\dfrac{\\ell}{g}}</span>. Chọn mốc thế năng tại vị trí cân bằng.</p><figure><img src=\"k11-bt/h/image97c0.png\" width=\"561\" height=\"448\" style=\"width:7.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Khi vật đi từ vị trí biên về vị trí cân bằng thì thế năng giảm và động năng tăng."], ["b", "Trong quá trình dao động, cơ năng biến thiên tuần hoàn."], ["c", "Một con lắc đơn góc lệch nhỏ (α ≤ 10°) thì chu kì T không phụ thuộc vào biên độ dao động."], ["d", "Khi vật di chuyển từ vị trí biên về vị trí cân bằng, thế năng giảm từ cực đại về 0."]], "col": 0, "da": "Đ S Đ S", "lg": ""}], "III": [{"than": "<p>Một chất điểm có khối lượng <span class=\"m\">m</span>, dao động điều hòa quanh vị trí cân bằng O với phương trình li độ có dạng <span class=\"m\">x=A\\cos \\left(\\omega t+\\varphi \\right)</span>. Sau những khoảng thời gian bằng nhau <span class=\"m\">\\Delta t=nT</span> động năng và thế năng bằng nhau. Hãy tìm n.</p><figure><img src=\"k11-bt/h/image99.png\" width=\"614\" height=\"393\" style=\"width:7.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "0,25", "lg": ""}, {"than": "<p>Một vật nhỏ có khối lượng 100 gam dao động điều hòa với chu kì <span class=\"m\">0{,}5\\pi\\ \\text{s}</span> và biên độ <span class=\"m\">3\\ \\text{cm}</span>. Chọn mốc thế năng tại vi trí cân bằng, cơ năng của vật bằng bao nhiêu mJ?</p>", "lc": [], "ds": [], "col": 0, "da": "0,72", "lg": ""}, {"than": "<p>Một vật nhỏ khối lượng 100 g dao động theo phương trình x = 8cos10t (x tính bằng cm, t tính bằng s). Động năng cực đại của vật bằng bao nhiêu mJ?</p>", "lc": [], "ds": [], "col": 0, "da": "32", "lg": ""}, {"than": "<p>Cho đồ thị như hình vẽ mô tả sự thay đổi thế năng theo li độ của một quả cầu có khối lượng 200 g đang dao động điều hòa dọc theo trục Ox, quanh gốc tọa độ O. Khi vật ở vị trí biên thế năng là bao nhiêu mJ?</p><figure><img src=\"k11-bt/h/image103.png\" width=\"510\" height=\"396\" style=\"width:5.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "100", "lg": ""}], "TL": []}, "B6": {"ten": "Bài 6. Dao động tắt dần. Dao động cưỡng bức. Hiện tượng cộng hưởng", "ch": "Chương I. Dao động", "dem": {"I": 18, "II": 2, "III": 3, "TL": 0}, "word": "k11-bt/word/Bai06_Tat_dan_cuong_buc_cong_huong.docx", "wordDa": "k11-bt/word/Bai06_Tat_dan_cuong_buc_cong_huong_Dap_an.docx", "wordCh": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong1_Dao_dong_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Một em bé đang chơi xích đu trong sân, nếu người mẹ chỉ đẩy một lần thì dao động của em bé và chiếc xích đu là</p>", "lc": [["A", "dao động tắt dần."], ["B", "dao động tuần hoàn."], ["C", "dao động tự do."], ["D", "dao động điều hòa."]], "ds": [], "col": 2, "da": "A", "lg": ""}, {"than": "<p>Dao động tắt dần là</p>", "lc": [["A", "dao động có biên độ giảm dần theo thời gian."], ["B", "dao động có biên độ tăng dần theo thời gian."], ["C", "dao động có biên độ giảm rồi tăng theo thời gian."], ["D", "dao động có biên độ tăng rồi giảm theo thời gian."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Nguyên nhân gây ra dao động tắt dần là do tác dụng của</p>", "lc": [["A", "lực căng dây."], ["B", "lực cản và lực ma sát của môi trường."], ["C", "trọng lực."], ["D", "lực đàn hồi của lò xo."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Khi một con lắc lò xo đang dao động tắt dần do tác dụng của lực ma sát thì cơ năng của con lắc chuyển hóa dần thành</p>", "lc": [["A", "điện năng."], ["B", "quang năng."], ["C", "hóa năng."], ["D", "nhiệt năng."]], "ds": [], "col": 4, "da": "D", "lg": ""}, {"than": "<p>Bộ giảm chấn khối lượng thường được sử dụng trong các tòa nhà cao tầng, các thiết bị đóng cửa tự động hay giảm xóc ô tô, xe máy là ứng dụng của</p>", "lc": [["A", "dao động duy trì."], ["B", "dao động cưỡng bức."], ["C", "dao động tắt dần."], ["D", "dao động điều hòa."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Trong những dao động tắt dần sau, trường hợp nào tắt dần nhanh có lợi?</p><figure><img src=\"k11-bt/h/image104.png\" width=\"764\" height=\"178\" style=\"width:16.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Dao động của quả lắc đồng hồ."], ["B", "Dao động của khung xe qua chỗ đường mấp mô."], ["C", "Dao động của xích đu."], ["D", "Dao động của con lắc đơn trong phòng thí nghiệm."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Hai chất điểm dao động có li độ phụ thuộc theo thời gian được biểu diễn tương ứng bởi hai đồ thị (1) và (2) như hình vẽ. Nhận xét nào dưới đây <b>đúng</b> khi nói về dao động của hai chất điểm?</p><figure><img src=\"k11-bt/h/image105c0.png\" width=\"349\" height=\"149\" style=\"width:6.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hai chất điểm đều thực hiện dao động điều hòa với cung chu kì."], ["B", "Đồ thị (1) biểu diễn chất điểm dao động tắt dần cùng chu kì với chất điểm còn lại."], ["C", "Hai chất điểm đều thực hiện dao động điều hòa và cùng pha ban đầu."], ["D", "Hai chất điểm đều thực hiện dao động tắt dần."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Dao động xảy ra dưới tác dụng của ngoại lực tuần hoàn có tần số f bất kì được gọi là</p>", "lc": [["A", "dao động tắt dần."], ["B", "dao động cưỡng bức."], ["C", "dao động duy trì."], ["D", "dao động cộng hưởng."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Khi đến bến xe buýt, xe chỉ tạm dừng nên không tắt máy, thân xe vẫn dao động. Dao động này là</p>", "lc": [["A", "dao động cưỡng bức."], ["B", "dao động tắt dần."], ["C", "dao động điện từ."], ["D", "dao động tự do."]], "ds": [], "col": 2, "da": "A", "lg": ""}, {"than": "<p>Máy đo địa chấn được sử dụng để phát hiện và đo đạc những rung động địa chấn được tạo ra bởi sự dịch chuyển của lớp vỏ Trái Đất. Năng lượng từ các cơn địa chấn có khả năng kích thích con lắc lò xo bên trong máy đo làm đầu bút di chuyển để vẽ lên giấy. Dao động của con lắc lò xo trong máy đo địa chấn khi cơn địa chấn xuất hiện là</p><figure><img src=\"k11-bt/h/image106.png\" width=\"332\" height=\"231\" style=\"width:3.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "dao động duy trì."], ["B", "dao động cưỡng bức."], ["C", "dao động điều hòa."], ["D", "dao động tự do."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Hiện tượng cộng hưởng xảy ra khi</p>", "lc": [["A", "tần số của lực cưỡng bức tiến đến bằng tần số riêng của hệ dao động."], ["B", "tần số của lực cưỡng bức nhỏ hơn tần số riêng của hệ dao động."], ["C", "tần số của lực cưỡng bức nhỏ hơn tần số riêng của hệ dao động."], ["D", "tần số của lực cưỡng bức lớn hơn tần số riêng của hệ dao động."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Hiện tượng cộng hưởng thể hiện rõ nét khi</p>", "lc": [["A", "tần số lực cưỡng bức nhỏ."], ["B", "lực cản môi trường nhỏ."], ["C", "tần số lực cưỡng bức lớn."], ["D", "biên độ lực cưỡng bức nhỏ."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Biên độ dao động cưỡng bức không thay đổi khi thay đổi</p>", "lc": [["A", "lực cản môi trường."], ["B", "pha ban đầu của lực cưỡng bức."], ["C", "biên độ lực cưỡng bức."], ["D", "tần số ngoại lực tuần hoàn."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Hộp đàn của đàn guitar, viôlon,... là những ứng dụng của</p>", "lc": [["A", "dao động tắt dần."], ["B", "dao động duy trì."], ["C", "hiện tượng cộng hưởng."], ["D", "dao động cưỡng bức."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Một cây cầu bắc ngang qua sông Fontanka ở Saint Petersburg (nước Nga) được thiết kế đủ vững chắc cho 300 người đi qua. Nhưng nó đã bị sập khi một trung đội bộ binh gồm 36 người đi đều qua vào năm 1960. Hiện tượng trên xảy ra là do</p>", "lc": [["A", "cây cầu dao động tắt dần."], ["B", "cầu không chịu được tải trọng."], ["C", "dao động tự do của cây cầu."], ["D", "hiện tượng cộng hưởng."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Hiện tượng cộng hưởng nào sau đây là có <b>hại</b>?</p>", "lc": [["A", "Khi máy bay di chuyển với tốc độ rất cao, cánh máy bay rung lắc mạnh vì cộng hưởng với các xoáy của dòng không khí."], ["B", "Các phân tử nước trong thực phẩm dao động cộng hưởng với tần số lò vi sóng hoạt động."], ["C", "Bầu đàn đóng vai trò của hộp cộng hưởng có khả năng cộng hưởng với nhiều tần số khác nhau và tăng cường độ âm với có các tần số đó."], ["D", "Không khí trong hộp đàn violon dao động cộng hưởng với tần số dao động của dây đàn."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Một hệ cơ học có tần số dao động riêng là 10 Hz ban đầu dao động cưỡng bức dưới tác dụng của ngoại lực biến thiên điều hoà <span class=\"m\">F_{1}</span> = <span class=\"m\">F_{0}</span> cos(20πt + π/12) (N) (t đo bằng giây). Nếu ta thay ngoại lực cưỡng bức <span class=\"m\">F_{1}</span> bằng ngoại lực cưỡng bức <span class=\"m\">F_{2}</span> = <span class=\"m\">F_{0}</span> cos(40πt + π/6) (N) (t đo bằng giây) thì biên độ dao động cưỡng bức của hệ</p>", "lc": [["A", "sẽ không đổi vì biên độ của lực không đổi."], ["B", "sẽ giảm vì mất cộng hưởng."], ["C", "sẽ tăng vì tần số biến thiên của lực tăng."], ["D", "sẽ giảm vì pha ban đầu của lực giảm."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Một con lắc đang dao động với tần số góc riêng 20 rad/s. Tác dụng một ngoại lực điều hòa cưỡng bức biên độ F và tần số <span class=\"m\">f_{1}</span> = 4 Hz theo phương trùng với trục của lò xo thì biên độ dao động ổn định <span class=\"m\">A_{1}</span>. Nếu giữ nguyên biên độ F và tăng tần số ngoại lực đến giá trị <span class=\"m\">f_{2}</span> = 5 Hz thì biên độ dao động ổn định <span class=\"m\">A_{2}</span>. So sánh <span class=\"m\">A_{1}</span> và <span class=\"m\">A_{2}</span>.</p>", "lc": [["A", "<span class=\"m\">A_{1}</span> = 2<span class=\"m\">A_{2}</span>."], ["B", "<span class=\"m\">A_{1}</span> ≥ <span class=\"m\">A_{2}</span>."], ["C", "<span class=\"m\">A_{1}</span> &lt; <span class=\"m\">A_{2}</span>."], ["D", "<span class=\"m\">A_{1}</span> &gt; <span class=\"m\">A_{2}</span>."]], "ds": [], "col": 4, "da": "D", "lg": ""}], "II": [{"than": "<p>Dao động tắt dần có nhiều ứng dụng trong cuộc sống.</p>", "lc": [], "ds": [["a", "Dao động tắt dần là dao động có biên độ giảm dần theo thời gian."], ["b", "Dao động của vật sẽ tắt dần nhanh hơn nếu tăng lực cản của môi trường."], ["c", "Trong dao động tắt dần, vận tốc của vật giảm liên tục theo thời gian."], ["d", "Dao động tắt dần được ứng dụng trong bộ phận giảm xóc của ô tô hoặc xe máy."]], "col": 0, "da": "Đ Đ S Đ", "lg": ""}, {"than": "<p>Một vật dao động trong không khí với tần số riêng <span class=\"m\">f_{0}</span> = 10 Hz thì chịu tác dụng của một ngoại lực biến thiên điều hòa. Đồ thị biểu diễn sự phụ thuộc biên độ dao động của vật vào tần số f của ngoại lực có dạng như hình vẽ.</p><figure><img src=\"k11-bt/h/image107.png\" width=\"365\" height=\"274\" style=\"width:5.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Dao động của vật là dao động cưỡng bức."], ["b", "Đặt hệ vật vào trong môi trường có lực cản lớn hơn thì độ lớn cực đại của biên độ dao động cưỡng bức sẽ tăng lên."], ["c", "Khi tần số của ngoại lực có giá trị f = 10 Hz thì xảy ra hiện tượng cộng hưởng."], ["d", "Khi ngoại lực thay đổi tần số từ giá trị <span class=\"m\">f_{1}</span> đến giá trị <span class=\"m\">f_{2}</span> thì biên độ dao động của vật tăng lên."]], "col": 0, "da": "Đ S Đ S", "lg": ""}], "III": [{"than": "<p>Một vật có tần số riêng 20 Hz đang thực hiện dao động cưỡng bức dưới tác dụng của ngoại lực tuần hoàn <span class=\"m\">F = 20\\cos (60\\pi t+\\pi)</span> (N) trong đó t tính theo giây (s). Tần số dao động của vật trong giai đoạn ổn định là bao nhiêu héc (Hz)? Làm tròn kết quả đến chữ số hàng đơn vị.</p>", "lc": [], "ds": [], "col": 0, "da": "30", "lg": ""}, {"than": "<p>Một con lắc lò xo có chu kì dao động riêng là <span class=\"m\">T_{0}</span> = 1 s. Tác dụng lên con lắc ngoại lực cưỡng bức biến đổi điều hòa theo phương trùng với trục của lò xo. Lực cưỡng bức có tần số góc bao nhiêu rad/s sẽ làm con lắc dao động mạnh nhất? Làm tròn kết quả đến chữ số hàng phần trăm.</p>", "lc": [], "ds": [], "col": 0, "da": "6,28", "lg": ""}, {"than": "<p>Một vật có khối lượng 200 g dao động dưới tác dụng của ngoại lực biến thiên điều hòa với tần số góc ω. Đồ thị biểu diễn sự phụ thuộc của biên độ vào tần số góc của ngoại lực tác dụng lên hệ có dạng như hình vẽ. Tính cơ năng của vật khi cộng hưởng theo đơn vị jun (J). Làm tròn kết quả đến chữ số hàng phần trăm.</p><figure><img src=\"k11-bt/h/image109.png\" width=\"384\" height=\"278\" style=\"width:4.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "0,36", "lg": ""}], "TL": []}, "B8": {"ten": "Bài 8. Mô tả sóng", "ch": "Chương II. Sóng", "dem": {"I": 9, "II": 2, "III": 5, "TL": 2}, "word": "k11-bt/word/Bai08_Mo_ta_song.docx", "wordDa": "k11-bt/word/Bai08_Mo_ta_song_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Sóng là</p>", "lc": [["A", "sự thay đổi vị trí của vật này so với vật khác theo thời gian."], ["B", "sự truyền chuyển động cơ trong chất rắn, lỏng, khí."], ["C", "những biến dạng cơ lan truyền trong môi trường đàn hồi."], ["D", "dao động của mọi điểm trong không gian."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Năng lượng sóng truyền qua một đơn vị diện tích vuông góc với phương truyền sóng trong một đơn vị thời gian gọi là</p>", "lc": [["A", "biên độ sóng."], ["B", "cường độ sóng."], ["C", "tần số sóng."], ["D", "bước sóng."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Một sóng hình sin truyền từ không khí vào nước thì đại lượng nào sau đây không đổi?</p>", "lc": [["A", "Bước sóng."], ["B", "Biên độ của sóng."], ["C", "Tốc độ truyền sóng."], ["D", "Tần số sóng."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Khoảng cách từ một phần tử môi trường bất kì trên phương truyền sóng đến phần tử gần nhất có trạng thái dao động hoàn toàn tương tự được gọi là</p>", "lc": [["A", "chu kì sóng."], ["B", "bước sóng."], ["C", "tốc độ truyền sóng."], ["D", "biên độ sóng."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Trong thí nghiệm tạo sóng nước, nếu ta thay đổi tần số dao động của nguồn sóng thì đại lượng nào sau đây không thay đổi?</p>", "lc": [["A", "Chu kì sóng."], ["B", "Bước sóng."], ["C", "Tần số sóng."], ["D", "Tốc độ truyền sóng."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Vào một thời điểm hình bên là đồ thị li độ - quãng đường truyền sóng của một sóng hình sin. Biên độ và bước sóng của sóng này lần lượt là</p><figure><img src=\"k11-bt/h/image110.png\" width=\"472\" height=\"304\" style=\"width:8.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "5 cm và 50 cm."], ["B", "6 cm và 50 cm."], ["C", "5 cm và 30 cm."], ["D", "6 cm và 30 cm."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Một sóng cơ khi truyền trong môi trường 1 có bước sóng và vận tốc là <span class=\"m\">\\lambda_{1}</span> và <span class=\"m\">v_{1}</span>. Khi truyền trong môi trường 2 có bước sóng và vận tốc là <span class=\"m\">\\lambda_{2}</span> và <span class=\"m\">v_{2}</span>. Biểu thức đúng là</p>", "lc": [["A", "<span class=\"m\">\\lambda_{2}</span> = <span class=\"m\">\\lambda_{1}</span>."], ["B", "<span class=\"m\">v_{2}</span> = <span class=\"m\">v_{1}</span>."], ["C", "<span class=\"m\">\\dfrac{\\lambda_2}{\\lambda_1}=\\dfrac{v_1}{v_2}</span>."], ["D", "<span class=\"m\">\\dfrac{\\lambda_1}{\\lambda_2}=\\dfrac{v_1}{v_2}</span>."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Một sóng cơ hình sin truyền theo trục Ox. Phương trình dao động của một phần tử trên Ox là u = 2cos10t (mm). Biên độ của sóng là</p>", "lc": [["A", "10 mm."], ["B", "4 mm."], ["C", "5 mm."], ["D", "2 mm."]], "ds": [], "col": 4, "da": "D", "lg": ""}, {"than": "<p>Một sóng cơ hình sin truyền theo trục Ox với chu kì T. Khoảng thời gian để sóng truyền được quãng đường bằng một bước sóng là</p>", "lc": [["A", "4T."], ["B", "0,5T."], ["C", "T."], ["D", "2T."]], "ds": [], "col": 4, "da": "C", "lg": ""}], "II": [{"than": "<p>Một sóng cơ truyền dọc theo phương Ox có đồ thị li độ - khoảng cách tại một thời điểm xác định được cho như hình vẽ. Biết chu kì của sóng là 0,5 giây.</p><figure><img src=\"k11-bt/h/image113.png\" width=\"586\" height=\"240\" style=\"width:9.0cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Độ lệch lớn nhất của phần tử sóng khỏi vị trí cân bằng là 3,0 cm."], ["b", "Chu kì của sóng bằng hai lần chu kì dao động của phần tử sóng."], ["c", "Tần số của sóng là số các ngọn sóng đi qua một điểm đang xét trong một đơn vị thời gian."], ["d", "Tốc độ truyền sóng là 16 cm/s."]], "col": 0, "da": "Đ S Đ Đ", "lg": ""}, {"than": "<p>Nhận định nào sau đây là đúng hay sai về tốc độ truyền sóng?</p>", "lc": [], "ds": [["a", "Tốc độ truyền sóng không thay đổi khi sóng truyền từ không khí vào nước."], ["b", "Tốc độ truyền sóng luôn bằng tốc độ dao động của phân tử có sóng truyền qua."], ["c", "Tốc độ truyền sóng được xác định bằng công thức v = λf với λ là bước sóng, f là tần số sóng."], ["d", "Tốc độ truyền sóng cơ học phụ thuộc vào đặc tính của môi trường truyền như mật độ vật chất, độ đàn hồi và nhiệt độ,….. của môi trường."]], "col": 0, "da": "S S Đ Đ", "lg": ""}], "III": [{"than": "<p>Ở 20 <span class=\"m\">^{o}</span> C và áp suất khí quyển 1 atm, một sóng âm có tần số 550 Hz truyền trong không khí với tốc độ là 343 m/s. Tìm bước sóng của sóng âm theo đơn vị mét. Làm tròn kết quả đến chữ số hàng phần trăm.</p>", "lc": [], "ds": [], "col": 0, "da": "0,62", "lg": ""}, {"than": "<p>Một sóng hình sin truyền trong một môi trường với tốc độ 1 m/s. Bước sóng trong môi trường đó bằng 30 cm. Tìm chu kì của sóng theo đơn vị giây (s). Làm tròn kết quả đến chữ số hàng phần mười.</p>", "lc": [], "ds": [], "col": 0, "da": "0,3", "lg": ""}, {"than": "<p>Tại một điểm O trên mặt nước có một nguồn dao động điều hòa theo phương thẳng đứng với tần số 2 Hz. Từ điểm O có những gợn sóng tròn lan rộng ra xung quanh. Khoảng cách giữa hai gợn sóng kế tiếp là 20 cm. Tính tốc độ truyền sóng trên mặt nước theo đơn vị cm/s. Làm tròn kết quả đến chữ số hàng đơn vị.</p>", "lc": [], "ds": [], "col": 0, "da": "40", "lg": ""}, {"than": "<p>Năm 2011 tại Nhật Bản, một trận động đất khởi phát ngoài khơi hòn đảo Honshu tạo nên sóng thần đổ xô từng đợt với tốc độ tiếp cận khoảng 800 km/h cách bờ biển khoảng 150 km. Tính thời gian (theo đơn vị phút) đợt sóng đầu tiên truyền tâm chấn đến bờ biển. Làm tròn kết quả đến chữ số hàng phần mười.</p>", "lc": [], "ds": [], "col": 0, "da": "11,3", "lg": ""}, {"than": "<p>Một tàu sử dụng hệ thống phát sóng âm để đo độ sâu của biển. Hệ thống phát ra các sóng âm và đo thời gian quay trở lại của sóng âm sau khi chúng bị phản xạ tại đáy biển. Tại một vị trí trên mặt biển, thời gian mà hệ thống ghi nhận được là 0,16 s kể từ khi sóng âm được truyền đi. Biết tốc độ truyền sóng âm trong nước biển không đổi là 1500 m/s. Tính độ sâu mực nước biển theo đơn vị mét. Làm tròn kết quả đến chữ số hàng đơn vị.</p><figure><img src=\"k11-bt/h/image114.png\" width=\"376\" height=\"253\" style=\"width:7.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "120", "lg": ""}], "TL": [{"than": "<p>Trên mặt hồ yên lặng, một người làm cho con thuyền dao động tạo ra sóng trên mặt nước. Thuyền thực hiện được 24 dao động trong 40 s, mỗi dao động tạo ra một ngọn sóng cao 12 cm so với mặt hồ yên lặng và ngọn sóng tới bờ cách thuyền 10 m sau 5 s.</p><p><b>a)</b> Tìm chu kì dao động của thuyền và tốc độ truyền sóng.</p><p><b>b)</b> Tìm bước sóng và biên độ sóng.</p>", "lc": [], "ds": [], "col": 0, "da": "a. 1,67 s; 2m/s; b) 3,33 m; 0,12 m.", "lg": ""}, {"than": "<p>Hình bên là hình ảnh của một sóng trên dây đàn hồi tại một thời điểm xác định. Cho biết thời gian ngắn nhất để điểm A từ vị trí cân bằng dao động theo phương thẳng đứng và trở lại vị trí này là 0,25 s và khoảng cách AB bằng 40 cm.</p><figure><img src=\"k11-bt/h/image115.png\" width=\"636\" height=\"169\" style=\"width:6.4cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Tính tốc độ truyền sóng trên dây.</p><p><b>b)</b> Tính khoảng cách CD.</p>", "lc": [], "ds": [], "col": 0, "da": "a. 1,6 m/s; b. 80 cm.", "lg": ""}]}, "B9": {"ten": "Bài 9. Sóng ngang. Sóng dọc. Sự truyền năng lượng của sóng cơ", "ch": "Chương II. Sóng", "dem": {"I": 11, "II": 2, "III": 0, "TL": 2}, "word": "k11-bt/word/Bai09_Song_ngang_song_doc.docx", "wordDa": "k11-bt/word/Bai09_Song_ngang_song_doc_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Để phân loại sóng dọc và sóng ngang người ta căn cứ vào</p>", "lc": [["A", "vận tốc truyền sóng và bước sóng."], ["B", "phương trình sóng và bước sóng."], ["C", "phương dao động của các phần tử môi trường với phương truyền sóng."], ["D", "phương dao động của các phần tử môi trường với vận tốc truyền sóng."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Sóng dọc là sóng có các phần tử dao động</p>", "lc": [["A", "theo phương vuông góc với phương truyền sóng."], ["B", "trùng với phương truyền sóng."], ["C", "theo phương ngang."], ["D", "theo phương thẳng đứng."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Sóng ngang là sóng có các phần tử dao động</p>", "lc": [["A", "theo phương vuông góc với phương truyền sóng."], ["B", "trùng với phương truyền sóng."], ["C", "theo phương ngang."], ["D", "theo phương thẳng đứng."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Sóng cơ truyền trên lò xo như hình a) và hình b). Nhận xét nào sau đây là đúng?</p><figure><img src=\"k11-bt/h/image116.png\" width=\"502\" height=\"207\" style=\"width:7.6cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Hình a) mô tả sóng dọc, b) mô tả sóng ngang."], ["B", "Hình a) mô tả sóng ngang, b) mô tả sóng dọc."], ["C", "Hình a) và b) mô tả sóng ngang."], ["D", "Hình a) và b) mô tả sóng dọc."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Sáng ngày 14/3/2022 một trận động đất 3,4 độ richter xảy ra ở huyện Điện Biên Đông tỉnh Điện Biên nhưng một số huyện tỉnh Sơn La cách huyện Điện Biên Đông 20 km nhưng nhà cửa, đồ đạc và vật dụng đều bị rung lắc chứng tỏ</p><figure><img src=\"k11-bt/h/image117.jpg\" width=\"677\" height=\"365\" style=\"width:7.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "quá trình truyền sóng là quá trình truyền năng lượng."], ["B", "quá trình truyền sóng là quá trình truyền vật chất."], ["C", "sóng luôn luôn là sóng ngang."], ["D", "sóng luôn luôn là sóng dọc."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Sóng cơ không truyền được trong</p>", "lc": [["A", "chân không."], ["B", "không khí."], ["C", "nước."], ["D", "kim loại."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Trong một buổi biểu diễn nhạc dân tộc, nghệ sĩ gảy dây đàn nguyệt làm dây đàn dao động, tạo ra âm lan truyền qua không khí đến tai người nghe. Âm truyền trong không khí là loại sóng gì và có phương dao động như thế nào?</p>", "lc": [["A", "Sóng ngang; phương dao động vuông góc với phương truyền sóng."], ["B", "Sóng dọc; phương dao động trùng với phương truyền sóng."], ["C", "Sóng ngang; phương dao động trùng với phương truyền sóng."], ["D", "Sóng dọc; phương dao động vuông góc với phương truyền sóng."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Trong phòng gym, một vận động viên tập luyện bài tập với dây thừng nặng (Battle Ropes). Vận động viên cầm một đầu dây cố định và giật mạnh tay lên xuống liên tục tạo ra các gợn sóng truyền dọc theo sợi dây về phía điểm cố định. Sóng trên dây thừng này thuộc loại sóng nào?</p><figure><img src=\"k11-bt/h/image118.png\" width=\"392\" height=\"249\" style=\"width:5.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "Sóng ngang."], ["B", "Sóng dọc."], ["C", "Sóng âm."], ["D", "Sóng điện từ."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Học sinh thực hành dùng đồ chơi lò xo Slinky đặt nằm ngang trên mặt bàn nhẵn. Học sinh dùng tay dồn nén một số vòng lò xo rồi thả nhẹ. Một vùng nén và giãn truyền đi dọc theo lò xo. Đây là mô hình minh họa trực quan cho</p>", "lc": [["A", "sự truyền của sóng ngang."], ["B", "sự truyền của sóng dọc."], ["C", "sự truyền của sóng điện từ."], ["D", "hiện tượng phản xạ toàn phần."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Mũi tên nào trong hình vẽ mô tả đúng hướng truyền dao động của các phần tử môi trường?</p><figure><img src=\"k11-bt/h/image119.png\" width=\"1024\" height=\"296\" style=\"width:12.3cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "↔."], ["B", "→."], ["C", "↑."], ["D", "↓."]], "ds": [], "col": 4, "da": "A", "lg": ""}, {"than": "<p>Chọn phát biểu <b>sai.</b> Quá trình lan truyền sóng là quá trình</p>", "lc": [["A", "truyền pha dao động."], ["B", "truyền dao động trong môi trường vật chất theo thời gian."], ["C", "truyền năng lượng."], ["D", "lan truyền các phần tử vật chất trong không gian theo thời gian."]], "ds": [], "col": 1, "da": "D", "lg": ""}], "II": [{"than": "<p>Hình bên mô tả quá trình lan truyền của sóng cơ trên một sợi dây đàn hồi tại thời điểm t. Biết rằng sóng lan truyền từ trái sang phải.</p><figure><img src=\"k11-bt/h/image120.png\" width=\"399\" height=\"142\" style=\"width:5.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Sóng truyền trên dây là sóng ngang."], ["b", "Phương dao động của M là phương ngang."], ["c", "Điểm M dao động sớm pha hơn điểm N."], ["d", "Điểm M sau 1 chu kì dao động sẽ di chuyển theo phương ngang."]], "col": 0, "da": "Đ S Đ S", "lg": ""}, {"than": "<p>Cấu tạo của tai người được mô tả như hình bên gồm 3 phần: tai ngoài, tai giữa và tai trong.</p><figure><img src=\"k11-bt/h/image121c0.png\" width=\"489\" height=\"285\" style=\"width:6.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p>- Tai ngoài đảm nhận chức năng thu và dẫn âm thanh; tai ngoài và tai giữa được ngăn cách bằng màng nhĩ, là màng kín, nhạy âm.</p><p>- Tai giữa giúp khuếch đại sóng âm thanh và truyền sóng âm đến tai trong.</p><p>- Tai trong: cung cấp thông tin thính giác.</p>", "lc": [], "ds": [["a", "Sóng âm truyền vào tai ngoài làm màng nhĩ dao động chứng tỏ quá trình truyền sóng là quá trình truyền năng lượng."], ["b", "Tần số của sóng âm càng lớn thì tần số dao động của màng nhĩ càng lớn, âm nghe càng cao."], ["c", "Âm thanh (sóng âm) lan truyền trong không khí là sóng ngang."], ["d", "Biên độ của sóng âm càng lớn thì biên độ dao động của màng nhĩ càng lớn, âm nghe càng to."]], "col": 0, "da": "Đ Đ S Đ", "lg": ""}], "III": [], "TL": [{"than": "<p>Dải tần số mà một học sinh có thể nghe thấy từ 30 Hz đến 16 000 Hz. Tốc độ truyền âm trong không khí là 330 m/s. Tính bước sóng lớn nhất của âm thanh trong không khí mà bạn học sinh đó nghe được.</p>", "lc": [], "ds": [], "col": 0, "da": "11", "lg": ""}, {"than": "<p>Một công nhân sửa chữa đường ray tàu hỏa dùng búa gõ mạnh vào thanh ray thép. Một người quan sát đứng cách đó 1020 m áp tai vào đường ray thì nghe thấy tiếng búa truyền qua thép, sau đó 2,8 s mới nghe thấy tiếng búa truyền qua không khí. Biết tốc độ truyền âm trong không khí là 340 m/s. Tính tốc độ truyền âm trong thép đường ray theo đơn vị m/s.</p>", "lc": [], "ds": [], "col": 0, "da": "5100", "lg": ""}]}, "B11": {"ten": "Bài 11. Sóng điện từ", "ch": "Chương II. Sóng", "dem": {"I": 12, "II": 1, "III": 2, "TL": 1}, "word": "k11-bt/word/Bai11_Song_dien_tu.docx", "wordDa": "k11-bt/word/Bai11_Song_dien_tu_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Sóng điện từ</p>", "lc": [["A", "là điện từ trường lan truyền trong không gian."], ["B", "là điện trường lan truyền trong không gian."], ["C", "là từ trường lan truyền trong không gian."], ["D", "là điện từ trường không lan truyền trong không gian."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Các sóng điện từ có tần số tăng dần theo thứ tự đúng là</p>", "lc": [["A", "tia gamma, tia X, tia tử ngoại, ánh sáng nhìn thấy, tia hồng ngoại, sóng vô tuyến."], ["B", "sóng vô tuyến, tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, tia X và tia gamma."], ["C", "tia gamma, tia X, tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, sóng vô tuyến."], ["D", "sóng vô tuyến, tia tử ngoại, ánh sáng nhìn thấy, tia hồng ngoại, tia X và tia gamma."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Tốc độ lan truyền của sóng điện từ trong chân không có giá trị bằng</p>", "lc": [["A", "<span class=\"m\">c=3.{10}^{5}</span> m/s."], ["B", "<span class=\"m\">c=3.{10}^{9}</span> m/s."], ["C", "<span class=\"m\">c=3.{10}^{8}</span> m/s."], ["D", "<span class=\"m\">c=3.{10}^{10}</span> m/s."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Sóng điện từ và sóng cơ học có cùng chung tính chất nào sau đây?</p>", "lc": [["A", "Đều có thể lan truyền được trong môi trường chân không."], ["B", "Đều là sóng dọc khi lan truyền trong môi trường chất rắn và chất lỏng."], ["C", "Đều có các hiện tượng phản xạ, khúc xạ, nhiễu xạ và giao thoa sóng."], ["D", "Tốc độ truyền sóng đều tăng lên khi mật độ vật chất của môi trường giảm."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Ánh sáng nhìn thấy là một phần của thang sóng điện từ, có dải bước sóng nằm trong khoảng nào trong chân không?</p>", "lc": [["A", "Từ 10 nm đến 400 nm."], ["B", "Từ 0,76 <span class=\"m\">\\mu</span> m đến 1 mm."], ["C", "Từ 0,38 <span class=\"m\">\\mu</span> m đến 0,76 <span class=\"m\">\\mu</span> m."], ["D", "Từ 30 pm đến 3 nm."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Trong vùng ánh sáng nhìn thấy, bức xạ có bước sóng dài nhất và bức xạ có bước sóng ngắn nhất lần lượt là</p>", "lc": [["A", "ánh sáng lục và ánh sáng vàng."], ["B", "ánh sáng đỏ và ánh sáng tím."], ["C", "ánh sáng tím và ánh sáng đỏ."], ["D", "ánh sáng lam và ánh sáng cam."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Tia hồng ngoại (IR) có đặc điểm và tính chất nào sau đây?</p>", "lc": [["A", "Là bức xạ điện từ nhìn thấy được có màu hồng nhạt rất đẹp mắt."], ["B", "Có bước sóng trong khoảng từ 0,76 um đến 1 mm, không nhìn thấy được bằng mắt thường."], ["C", "Có khả năng kích thích sự phát quang của rất nhiều chất hóa học độc hại."], ["D", "Chỉ được phát ra từ những vật được nung nóng tới nhiệt độ cực cao trên 2000 °C."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Nguồn phát nào sau đây thông dụng nhất để phát ra tia hồng ngoại trong đời sống?</p>", "lc": [["A", "Đèn hơi thủy ngân công suất lớn."], ["B", "Hồ quang điện dùng trong công nghiệp hàn kim loại."], ["C", "Bóng đèn dây tóc, bếp gas, bếp than hoặc chính cơ thể con người."], ["D", "Máy chụp bức xạ cắt lớp vi tính trong bệnh viện."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Điều kiện để một vật phát ra tia tử ngoại mạnh mẽ truyền ra môi trường xung quanh là nhiệt độ của vật phải</p>", "lc": [["A", "cao hơn nhiệt độ môi trường xung quanh một chút (trên 37 °C)."], ["B", "rất thấp dưới 0 °C để các nguyên tử bị kích thích dao động mạnh."], ["C", "đạt từ 500 °C đến 1000 °C để nguyên tử chuyển trạng thái dừng."], ["D", "đạt nhiệt độ rất cao, thông thường là trên 2000 °C."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Trong y học, tia Rơn-ghen (tia X) được ứng dụng rộng rãi nhất để</p>", "lc": [["A", "chụp X-quang để hỗ trợ chẩn đoán bệnh và tổn thương trong cơ thể, đặc biệt là xương."], ["B", "sấy khô thực phẩm và diệt khuẩn bề mặt các dụng cụ phẫu thuật."], ["C", "kích thích các tế bào biểu bì da tự tổng hợp vitamin D tự nhiên."], ["D", "chụp ảnh hồng ngoại tầm nhiệt để đo thân nhiệt từ xa của bệnh nhân."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Bức xạ điện từ có bước sóng rất ngắn (từ <span class=\"m\">{10}^{-14}</span> m đến 0,1 nm), năng lượng cao, khả năng đâm xuyên mạnh, dùng xạ trị trong y học … là</p>", "lc": [["A", "bức xạ hồng ngoại."], ["B", "bức xạ tử ngoại"], ["C", "bức xạ Rơn-ghen."], ["D", "bức xạ gamma."]], "ds": [], "col": 4, "da": "D", "lg": ""}, {"than": "<p>Sóng vô tuyến dải tần số cực cao UHF (Ultra High Frequency, bước sóng từ 10 cm đến 1 m) có đặc điểm nổi bật là</p>", "lc": [["A", "bị tầng điện li của Trái Đất phản xạ rất mạnh mẽ để truyền đi xa vòng quanh Trái Đất."], ["B", "có thể truyền thẳng đến máy thu, không bị phản xạ ở tầng điện li."], ["C", "bị nước biển hấp thụ hoàn toàn nên chỉ dùng liên lạc cho tàu ngầm ở tầng sâu."], ["D", "có tốc độ lan truyền chậm hơn nhiều so với các dải sóng vô tuyến khác."]], "ds": [], "col": 1, "da": "B", "lg": ""}], "II": [{"than": "<p>Máy sấy và tiệt trùng bát đĩa được sử dụng trong nhà bếp. Máy tích hợp 3 tính năng: bộ phận sưởi phát bức xạ nhiệt giúp làm khô bát đĩa, đèn tử ngoại (UV) hỗ trợ khử khuẩn bề mặt bát đĩa và bộ điều khiển từ xa (remote) sử dụng tia hồng ngoại phát tín hiệu điều khiển. Các nhận định dưới đây về máy là <b>đúng</b> hay <b>sai</b>?</p><figure><img src=\"k11-bt/h/image122c0.png\" width=\"442\" height=\"540\" style=\"width:4.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Bức xạ hồng ngoại do remote phát ra và thành phần bức xạ hồng ngoại phát ra từ bộ phận sưởi đều thuộc vùng hồng ngoại của phổ điện từ."], ["b", "Tia tử ngoại (UV) có khả năng diệt vi khuẩn và mầm bệnh."], ["c", "Theo thiết kế của thiết bị, cửa được làm bằng vật liệu ngăn tia UV truyền ra ngoài."], ["d", "Bức xạ có tác dụng chính để sấy khô bát đĩa trong máy là của tia tử ngoại."]], "col": 0, "da": "Đ Đ Đ S", "lg": ""}], "III": [{"than": "<p>Một đài truyền hình địa phương phát sóng truyền hình mặt đất bằng sóng điện từ thuộc dải UHF có tần số <span class=\"m\">f = 600\\ \\text{MHz}</span>. Coi tốc độ truyền sóng điện từ trong chân không là <span class=\"m\">c=3.{10}^{8} m/s</span>. Bước sóng của tín hiệu này trong chân không là bao nhiêu mét? Kết quả làm tròn đến chữ số hàng phần trăm.</p>", "lc": [], "ds": [], "col": 0, "da": "0,50", "lg": ""}, {"than": "<p>Một vệ tinh cách trạm thu trên mặt đất 36000 km. Một tín hiệu vô tuyến truyền từ vệ tinh đến trạm thu. Coi tín hiệu truyền với tốc độ <span class=\"m\">c=3.{10}^{8} m/s</span>. Thời gian tín hiệu truyền đến trạm thu xấp xỉ bằng bao nhiêu mili giây (ms)?</p>", "lc": [], "ds": [], "col": 0, "da": "120", "lg": ""}], "TL": [{"than": "<p>Một anten phát sóng vô tuyến đặt tại mặt đất phát ra một sóng điện từ truyền thẳng hướng lên một vệ tinh truyền thông đang ở quỹ đạo địa tĩnh ở độ cao h = 36000 km so với anten mặt đất. Tín hiệu truyền từ anten đến vệ tinh mất một khoảng thời gian Δt. Sóng vô tuyến này có bước sóng <span class=\"m\">\\lambda_{0} = 15\\ \\text{cm}</span> trong không khí (được coi là chân không).</p><p><b>a)</b> Tính tần số f của sóng vô tuyến này và cho biết nó thuộc dải sóng vô tuyến nào?</p><p><b>b)</b> Tính thời gian Δt để tín hiệu đi từ anten mặt đất lên tới vệ tinh.</p><figure><img src=\"k11-bt/h/image123.png\" width=\"1430\" height=\"742\" style=\"width:14.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "a) <span class=\"m\">2.{10}^{9}</span> Hz; b) 0,12 s.", "lg": ""}]}, "B12": {"ten": "Bài 12. Giao thoa sóng", "ch": "Chương II. Sóng", "dem": {"I": 10, "II": 2, "III": 7, "TL": 2}, "word": "k11-bt/word/Bai12_Giao_thoa_song.docx", "wordDa": "k11-bt/word/Bai12_Giao_thoa_song_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Hai nguồn sóng kết hợp là hai nguồn dao động</p>", "lc": [["A", "cùng biên độ và cùng pha."], ["B", "cùng phương, cùng tần số và có độ lệch pha không đổi theo thời gian."], ["C", "cùng tần số và cùng biên độ."], ["D", "cùng phương và có độ lệch pha thay đổi theo thời gian."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Hiện tượng giao thoa của hai sóng là hiện tượng</p>", "lc": [["A", "hai sóng gặp nhau rồi truyền tiếp mà không thay đổi gì."], ["B", "hai sóng gặp nhau tạo nên các gợn sóng ổn định (các vân giao thoa)."], ["C", "hai sóng gặp nhau và triệt tiêu nhau tại mọi điểm."], ["D", "hai sóng cùng truyền theo một phương và tăng cường nhau tại mọi điểm."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Trong vùng giao thoa của hai sóng phát ra từ hai nguồn kết hợp cùng pha, điểm dao động với biên độ cực đại có hiệu đường đi d₂ − d₁ thỏa mãn (k ∈ ℤ):</p>", "lc": [["A", "d₂ − d₁ = kλ."], ["B", "d₂ − d₁ = (k + ½)λ."], ["C", "d₂ − d₁ = kλ/2."], ["D", "d₂ − d₁ = (2k + 1)λ."]], "ds": [], "col": 2, "da": "A", "lg": ""}, {"than": "<p>Với hai nguồn kết hợp cùng pha, điểm đứng yên (biên độ cực tiểu) trong vùng giao thoa có hiệu đường đi thỏa mãn (k ∈ ℤ):</p>", "lc": [["A", "d₂ − d₁ = kλ."], ["B", "d₂ − d₁ = 2kλ."], ["C", "d₂ − d₁ = (k + ½)λ."], ["D", "d₂ − d₁ = kλ/4."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Trong thí nghiệm giao thoa hai sóng mặt nước, khi cần rung có gắn hai quả cầu dao động, hình ảnh quan sát được trên màn là</p><figure><img src=\"k11-bt/h/image124c0.png\" width=\"381\" height=\"301\" style=\"width:7.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "các vòng tròn sáng, tối đồng tâm lan ra từ một tâm dao động."], ["B", "các gợn sóng chuyển động hỗn loạn, không ổn định."], ["C", "các đường sáng và tối ổn định, hình dạng hypebol, xen kẽ nhau."], ["D", "mặt nước hoàn toàn đứng yên, không có gợn sóng."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Thí nghiệm Young về giao thoa ánh sáng chứng tỏ</p>", "lc": [["A", "ánh sáng có tính chất sóng."], ["B", "ánh sáng truyền thẳng trong mọi môi trường."], ["C", "ánh sáng là dòng các hạt chuyển động thẳng đều."], ["D", "ánh sáng chỉ truyền được trong chân không."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Trong thí nghiệm Young, gọi a là khoảng cách hai khe, D là khoảng cách từ hai khe đến màn, λ là bước sóng ánh sáng. Khoảng vân i được xác định bởi công thức</p>", "lc": [["A", "<span class=\"m\">i=\\dfrac{\\lambda a}{D}</span>."], ["B", "<span class=\"m\">i=\\dfrac{\\lambda D}{a}</span>."], ["C", "<span class=\"m\">i=\\dfrac{aD}{\\lambda}</span>."], ["D", "<span class=\"m\">i=\\dfrac{\\lambda}{aD}</span>."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Giao thoa ánh sáng đơn sắc là hiện tượng</p>", "lc": [["A", "xuất hiện các vạch sáng xen kẽ với các vạch tối khi hai sóng ánh sáng kết hợp gặp nhau."], ["B", "xuất hiện các vạch sáng xen kẽ với các vạch tối khi hai sóng ánh sáng gặp nhau."], ["C", "chỉ xảy ra với ánh sáng đỏ."], ["D", "xuất hiện các vạch sáng trắng xen kẽ với các vạch tối khi hai sóng ánh sáng kết hợp gặp nhau."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Chọn câu sai khi nói về giao thoa ánh sáng.</p>", "lc": [["A", "Hiện tượng giao thoa ánh sáng chỉ giải thích được bằng sự giao thoa của hai sóng kết hợp."], ["B", "Hiện tượng giao thoa ánh sáng khẳng định ánh sáng có tính chất sóng."], ["C", "Trong miền giao thoa, những vạch sáng ứng với những chỗ hai sóng gặp nhau tăng cường lẫn nhau."], ["D", "Trong miền giao thoa, những vạch tối ứng với những chỗ hai sóng không gặp được nhau."]], "ds": [], "col": 1, "da": "D", "lg": ""}, {"than": "<p>Trong hệ vân giao thoa ánh sáng của thí nghiệm Young, các vạch tối là những chỗ</p>", "lc": [["A", "hai sóng ánh sáng tăng cường lẫn nhau."], ["B", "chỉ có một sóng ánh sáng truyền tới."], ["C", "hai sóng ánh sáng triệt tiêu lẫn nhau."], ["D", "ánh sáng bị màn chắn hấp thụ hoàn toàn."]], "ds": [], "col": 1, "da": "C", "lg": ""}], "II": [{"than": "<p>Khảo sát hiện tượng giao thoa sóng cơ trên mặt nước với hai nguồn kết hợp S₁, S₂ dao động cùng phương, cùng pha, cùng tần số. Trong vùng hai sóng gặp nhau xuất hiện những điểm dao động với biên độ cực đại và những điểm dao động với biên độ cực tiểu (đứng yên).</p>", "lc": [], "ds": [["a", "Hai nguồn S₁, S₂ là hai nguồn kết hợp vì chúng dao động cùng phương, cùng tần số và có độ lệch pha không đổi theo thời gian."], ["b", "Tại một điểm dao động với biên độ cực đại, hai sóng từ hai nguồn truyền tới dao động cùng pha với nhau."], ["c", "Những điểm dao động với biên độ cực tiểu (đứng yên) là những điểm mà hai sóng truyền tới ngược pha và triệt tiêu lẫn nhau."], ["d", "Trên đoạn thẳng nối hai nguồn, khoảng cách giữa hai điểm dao động cực đại liên tiếp bằng một bước sóng."]], "col": 0, "da": "Đ Đ Đ S", "lg": ""}, {"than": "<p>Khảo sát hiện tượng giao thoa ánh sáng bằng thí nghiệm Young: hai khe hẹp F₁, F₂ song song được chiếu bằng ánh sáng đơn sắc. Màn quan sát đặt song song với mặt phẳng chứa hai khe. Trên màn thu được hệ vân giao thoa gồm các vân sáng và vân tối xen kẽ, cách đều nhau, chứng tỏ ánh sáng có tính chất sóng.</p>", "lc": [], "ds": [["a", "Hai khe hẹp F₁, F₂ đóng vai trò là hai nguồn sáng kết hợp."], ["b", "Vân tối trên màn là chỗ hai sóng ánh sáng từ hai khe truyền tới tăng cường lẫn nhau."], ["c", "Tại vị trí vân sáng, hai sóng ánh sáng từ hai khe truyền tới dao động cùng pha nên tăng cường lẫn nhau."], ["d", "Khi giữ nguyên các điều kiện khác và tăng khoảng cách từ hai khe đến màn thì khoảng vân trên màn tăng lên."]], "col": 0, "da": "Đ S Đ Đ", "lg": ""}], "III": [{"than": "<p>Trên mặt nước có hai nguồn sóng cơ kết hợp, dao động cùng phương, cùng tần số, cùng pha nhau. Sóng trên mặt nước có tần số 20 Hz. Điểm M trên mặt nước cách <span class=\"m\">S_{1}</span> và <span class=\"m\">S_{2}</span> lần lượt 26 cm và 20 cm, đồng thời có biên độ cực đại. Tốc độ truyền sóng trên mặt nước là bao nhiêu cm/s?</p><figure><img src=\"k11-bt/h/image125.png\" width=\"485\" height=\"408\" style=\"width:6.7cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "60", "lg": ""}, {"than": "<p>Trong một thí nghiệm giao thoa sóng trên mặt nước, cần rung tạo hai nguồn kết hợp <span class=\"m\">S_{1}</span> và <span class=\"m\">S_{2}</span> dao động cùng pha cùng tần số <b>5 Hz</b>. Khi ổn định, học sinh thấy trên đoạn thẳng nối hai nguồn S₁, S₂ các điểm dao động cực đại nằm cách đều nhau, khoảng cách giữa hai điểm cực đại <b>cạnh nhau là 4 cm</b>. Tốc độ truyền sóng trên mặt nước là bao nhiêu cm/s?</p>", "lc": [], "ds": [], "col": 0, "da": "40", "lg": ""}, {"than": "<p>Trong bài thực hành đo bước sóng ánh sáng bằng khe Young của học sinh. Ánh sáng đơn sắc có bước sóng <b>0,6 μm,</b> hai khe hẹp cách nhau <b>0,3 mm</b>. Màn quan sát đặt song song và cách mặt phẳng chứa hai khe <b>1,5 m</b>. Khoảng vân giao thoa trên màn là bao nhiêu mm?</p>", "lc": [], "ds": [], "col": 0, "da": "3", "lg": ""}, {"than": "<p>Trong thí nghiệm Young về giao thoa với ánh sáng đơn sắc, hai khe cách nhau <b>0,5 mm</b> và màn cách hai khe <b>1,5 m</b>. Để giảm sai số học sinh không đo một khoảng vân đơn lẻ mà đo khoảng cách giữa <b>10 vân sáng liên tiếp</b> được kết quả <b>13,5 mm</b>. Bước sóng λ của ánh sáng dùng trong thí nghiệm là bao nhiêu <span class=\"m\">\\mu m</span>?</p>", "lc": [], "ds": [], "col": 0, "da": "0,5", "lg": ""}, {"than": "<p>Trong thí nghiệm giao thoa ánh sáng đơn sắc với hai khe Young, một học sinh xác định được khoảng vân trên màn là <b>1,2 mm</b>. Trên màn khoảng cách từ <b>vân sáng bậc 4</b> đến vân sáng trung tâm là bao nhiêu mm?</p>", "lc": [], "ds": [], "col": 0, "da": "4,8", "lg": ""}, {"than": "<p>Trong thí nghiệm Young về giao thoa ánh sáng. Ánh sáng đươc dùng có bước sóng <b>0,60 μm</b>. Biết tốc độ ánh sáng trong chân không <b>c = 3.10⁸ m/s</b>. Tần số của ánh sáng đơn sắc này là f = x.10¹⁴ Hz. Giá trị của x là bao nhiêu?</p>", "lc": [], "ds": [], "col": 0, "da": "5", "lg": ""}, {"than": "<p>Trong thí nghiệm Young về giao thoa ánh sáng, hai khe hẹp cách nhau <b>0,6 mm</b>. Ban đầu khoảng vân đo được trên màn là <b>1 mm</b>. Giữ nguyên nguồn sáng và hai khe, học sinh tịnh tiến màn quan sát theo phương vuông góc mặt phẳng chứa hai khe và <b>lại gần</b> hai khe một đoạn <b>25 cm</b> thì đo được khoảng vân mới là <b>0,8 mm</b>. Bước sóng λ của ánh sáng là bao nhiêu <span class=\"m\">\\mu m</span>?</p>", "lc": [], "ds": [], "col": 0, "da": "0,48", "lg": ""}], "TL": [{"than": "<p>Cho hai loa giống hệt nhau, cùng nối với một máy phát âm tần nên phát ra âm hoàn toàn giống nhau (hình bên dưới). Âm phát ra có tần số 850 Hz, tốc độ truyền âm trong không khí là 340 m/s. Khi di chuyển một micro có nối với dao động kí dọc theo một đường thẳng phía trước hai loa thì thấy có những điểm tại đó biên độ sóng âm thu được rất lớn (L) và những điểm biên độ rất bé nằm xen kẽ nhau.</p><figure><img src=\"k11-bt/h/image126.png\" width=\"602\" height=\"495\" style=\"width:6.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Vận dụng kiến thức về giao thoa sóng, hãy giải thích hiện tượng thú vị này.</p><p><b>b)</b> Tính bước sóng.</p>", "lc": [], "ds": [], "col": 0, "da": "a) - Hai sóng âm do chúng phát ra là hai sóng kết hợp, khi gặp nhau xảy ra hiện tượng giao thoa: tại những điểm hai sóng luôn đồng pha chúng tăng cường nhau → âm nghe rất to (điểm L); tại những điểm hai sóng luôn ngược pha chúng triệt tiêu nhau → âm rất bé (điểm B). Các điểm L và B có vị trí ổn định, nằm xen kẽ nhau tạo thành hệ vân giao thoa của sóng âm.", "lg": "<p>b) 40 cm.</p>"}, {"than": "<p>Trong thí nghiệm Young về giao thoa ánh sáng, nguồn sáng hẹp phát ra ánh sáng đơn sắc có bước sóng λ = 0,6 μm. Khoảng cách giữa hai khe là a = 1 mm, khoảng cách từ mặt phẳng chứa hai khe đến màn quan sát ban đầu là D = 1,5 m.</p><p><b>a)</b> Tính khoảng vân trên màn và khoảng cách từ vân sáng bậc 3 đến vân tối thứ 5 ở hai phía so với vân sáng trung tâm.</p><p><b>b)</b> Gọi M là một điểm trên màn quan sát, ban đầu cách vân sáng trung tâm một đoạn 4,5 mm. Giữ cố định các điều kiện khác, dời màn quan sát từ từ dọc theo đường thẳng vuông góc với mặt phẳng chứa hai khe, tiến lại gần hai khe thêm một đoạn tối đa 0,9 m. Trong quá trình dời màn, tại điểm M quan sát được bao nhiêu lần chuyển thành vân tối?</p>", "lc": [], "ds": [], "col": 0, "da": "a/ 0,9 mm; 6,75 mm; b/ 8 lần.", "lg": ""}]}, "B13": {"ten": "Bài 13. Sóng dừng", "ch": "Chương II. Sóng", "dem": {"I": 10, "II": 2, "III": 7, "TL": 2}, "word": "k11-bt/word/Bai13_Song_dung.docx", "wordDa": "k11-bt/word/Bai13_Song_dung_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Sóng dừng được tạo thành khi</p>", "lc": [["A", "hai sóng có biên độ khác nhau truyền cùng chiều gặp nhau."], ["B", "hai sóng cùng biên độ, cùng bước sóng lan truyền theo hai hướng ngược nhau gặp nhau, giao thoa với nhau."], ["C", "một sóng bị vật cản hấp thụ hoàn toàn."], ["D", "hai sóng có tần số khác nhau truyền ngược chiều gặp nhau."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Trong sóng dừng, nút sóng là những điểm tại đó hai sóng thành phần</p>", "lc": [["A", "đồng pha với nhau nên dao động với biên độ cực đại."], ["B", "vuông pha với nhau nên dao động với biên độ trung bình."], ["C", "ngược pha với nhau nên không dao động (đứng yên)."], ["D", "cùng tần số nên dao động rất mạnh."]], "ds": [], "col": 1, "da": "C", "lg": ""}, {"than": "<p>Trong sóng dừng, bụng sóng là những điểm</p>", "lc": [["A", "luôn đứng yên."], ["B", "dao động với biên độ cực đại do hai sóng đồng pha với nhau."], ["C", "chỉ dao động khi tần số rất lớn."], ["D", "có biên độ bằng biên độ của một sóng thành phần."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Trên một sợi dây có sóng dừng, hai nút sóng liên tiếp cách nhau một khoảng bằng</p>", "lc": [["A", "λ."], ["B", "<span class=\"m\">\\dfrac{\\lambda}{2}</span>."], ["C", "<span class=\"m\">\\dfrac{\\lambda}{4}</span>."], ["D", "2λ."]], "ds": [], "col": 4, "da": "B", "lg": ""}, {"than": "<p>Trong thí nghiệm tạo sóng dừng trên dây có hai đầu cố định, L là chiều dài của dây, <span class=\"m\">\\lambda</span> là bước sóng. Điều kiện để có sóng dừng là chiều dài dây phải bằng</p>", "lc": [["A", "<span class=\"m\">L=\\dfrac{n\\lambda}{2}</span>, với n = 1, 2, 3,...."], ["B", "L = nλ, với n = 1, 2, 3,..."], ["C", "<span class=\"m\">L=\\dfrac{(2n+1)\\lambda}{4}</span>, với n = 0, 1, 2, 3,..."], ["D", "<span class=\"m\">L=\\dfrac{n\\lambda}{4}</span>, với n = 1, 2, 3,..."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Một ống sáo có một đầu kín, một đầu hở. Điều kiện để có sóng dừng trong cột không khí của ống sáo là chiều dài của ống phải bằng</p>", "lc": [["A", "một số nguyên lần nửa bước sóng."], ["B", "một số chẵn lần một phần tư bước sóng."], ["C", "một số nguyên lần bước sóng."], ["D", "một số lẻ lần một phần tư bước sóng."]], "ds": [], "col": 2, "da": "D", "lg": ""}, {"than": "<p>Trong thí nghiệm tạo sóng dừng trên dây PQ hình, người ta điều chỉnh tần số của bộ rung cho đến khi</p><figure><img src=\"k11-bt/h/image127.png\" width=\"478\" height=\"542\" style=\"width:5.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "trên dây xuất hiện những điểm dao động với biên độ cực đại xen kẽ những điểm đứng yên."], ["B", "mọi điểm trên dây đều dao động với biên độ như nhau."], ["C", "sợi dây bị đứt do dao động quá mạnh."], ["D", "toàn bộ sợi dây đứng yên hoàn toàn."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Sóng dừng trên một sợi dây đàn hồi chiều dài L được mô tả như hình. Số nút sóng (kể cả hai đầu dây) và số bụng sóng trên dây là</p><figure><img src=\"k11-bt/h/image128.png\" width=\"389\" height=\"210\" style=\"width:6.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "hai nút sóng và ba bụng sóng."], ["B", "ba nút sóng và bốn bụng sóng."], ["C", "bốn nút sóng và ba bụng sóng."], ["D", "bốn nút sóng và sáu bụng sóng."]], "ds": [], "col": 2, "da": "C", "lg": ""}, {"than": "<p>Một trong những ứng dụng hiện tượng sóng dừng để xác định</p>", "lc": [["A", "tần số sóng."], ["B", "tốc độ truyền sóng."], ["C", "năng lượng sóng."], ["D", "cường độ sóng."]], "ds": [], "col": 2, "da": "B", "lg": ""}, {"than": "<p>Khi gảy đàn ghita, trên dây đàn (hai đầu cố định, chiều dài L) xuất hiện sóng dừng và đàn phát ra âm cơ bản có tần số <span class=\"m\">f=\\dfrac{v}{2L}</span>. Khi ấn ngón tay vào các phím khác nhau, âm phát ra có độ cao khác nhau vì</p>", "lc": [["A", "lực căng dây thay đổi làm biên độ sóng thay đổi."], ["B", "chiều dài dây dao động thay đổi làm tần số âm phát ra thay đổi."], ["C", "tốc độ truyền sóng trên dây thay đổi còn chiều dài dây không đổi."], ["D", "thùng đàn cộng hưởng làm thay đổi tần số của âm."]], "ds": [], "col": 1, "da": "B", "lg": ""}], "II": [{"than": "<p>Trong thí nghiệm tạo sóng dừng như hình, sợi dây PQ dài 1,2 m có hai đầu cố định. Khi bộ rung dao động với tần số 50 Hz thì trên dây quan sát được sóng dừng với 4 bụng sóng.</p><figure><img src=\"k11-bt/h/image129.jpg\" width=\"611\" height=\"692\" style=\"width:7.1cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Sóng dừng trên dây là kết quả giao thoa giữa sóng tới và sóng phản xạ truyền ngược chiều nhau trên dây."], ["b", "Bước sóng của sóng trên dây bằng 0,6 m."], ["c", "Tốc độ truyền sóng trên dây bằng 60 m/s."], ["d", "Trên dây có 5 nút sóng (kể cả hai đầu P, Q)."]], "col": 0, "da": "Đ Đ S Đ", "lg": ""}, {"than": "<p>Một ống khí hình trụ dài L = 0,5 m có một đầu kín, một đầu hở. Trong ống có sóng dừng của sóng âm, bước sóng <span class=\"m\">\\lambda</span>. Tốc độ truyền âm trong không khí là 340 m/s.</p>", "lc": [], "ds": [["a", "Khi có hiện tượng cộng hưởng âm thì tại đầu kín của ống là một nút sóng, tại đầu hở là một bụng sóng."], ["b", "Điều kiện để có sóng dừng trong ống khi là L = <span class=\"m\">\\dfrac{n\\lambda}{2}</span> với n = 1, 2, 3,..."], ["c", "Bước sóng dài nhất của sóng dừng có thể có trong ống là 2 m."], ["d", "Tần số âm nhỏ nhất mà ống có thể tạo sóng dừng là 170 Hz."]], "col": 0, "da": "Đ S Đ Đ", "lg": ""}], "III": [{"than": "<p>Trên một sợi dây có sóng dừng, hai nút sóng liên tiếp cách nhau 25 cm. Bước sóng của sóng trên dây là bao nhiêu cm?</p>", "lc": [], "ds": [], "col": 0, "da": "50", "lg": ""}, {"than": "<p>Một dây đàn hồi dài 0,6 m hai đầu cố định dao động tạo sóng dừng với 3 bụng sóng. Bước sóng của sóng trên dây là bao nhiêu mét?</p>", "lc": [], "ds": [], "col": 0, "da": "0,4", "lg": ""}, {"than": "<p>Trên sợi dây đàn hồi có chiều dài L = 1,2 m (hai đầu cố định), người ta tạo ra sóng dừng có hình dạng như Hình 3 (3 bụng sóng). Biết tần số rung của sợi dây là f = 13,3 Hz. Tốc độ truyền sóng trên dây là bao nhiêu m/s? Kết quả làm tròn đến hàng phần mười.</p>", "lc": [], "ds": [], "col": 0, "da": "10,6", "lg": ""}, {"than": "<p>Một dây đàn ghita dài 0,64 m có hai đầu cố định, tốc độ truyền sóng trên dây là 422,4 m/s. Khi gảy, dây dao động với một bụng sóng. Tần số âm do dây đàn phát ra là bao nhiêu Hz? Kết quả làm tròn đến hàng đơn vị.</p><figure><img src=\"k11-bt/h/image130.png\" width=\"516\" height=\"132\" style=\"width:6.9cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [], "col": 0, "da": "330", "lg": ""}, {"than": "<p>Một sợi dây dài 1,0 m có một đầu cố định, một đầu tự do. Bước sóng dài nhất của sóng dừng có thể tạo được trên dây là bao nhiêu mét?</p>", "lc": [], "ds": [], "col": 0, "da": "4", "lg": ""}, {"than": "<p>Trên một sợi dây có sóng dừng, khoảng cách giữa 5 nút sóng liên tiếp là 80 cm. Tốc độ truyền sóng trên dây là 8 m/s. Tần số sóng là bao nhiêu Hz?</p>", "lc": [], "ds": [], "col": 0, "da": "20", "lg": ""}, {"than": "<p>Một sợi dây đàn hồi hai đầu cố định, dài 0,9 m. Trên dây đang có sóng dừng với tổng cộng 4 nút sóng (kể cả hai đầu dây). Bước sóng của sóng trên dây bằng bao nhiêu mét?</p>", "lc": [], "ds": [], "col": 0, "da": "0,6", "lg": ""}], "TL": [{"than": "<p>Thí nghiệm tạo sóng dừng trên một sợi dây đàn hồi dài 0,5 m có hai đầu cố định. Tốc độ truyền sóng trên dây là 4 m/s.</p><p><b>a)</b> Khi tần số của sóng bằng 400 Hz, hãy xác định bước sóng của sóng trên dây.</p><p><b>b)</b> Hãy xác định tần số của sóng để trung điểm của dây là một nút sóng. Biết rằng tần số sóng có giá trị từ 425 Hz đến 437 Hz.</p>", "lc": [], "ds": [], "col": 0, "da": "a) 1 cm. b) 432 Hz.", "lg": ""}, {"than": "<p>Sợi dây đàn hồi PQ dài 1,2 m có hai đầu cố định, được kích thích dao động bằng một bộ rung có thể thay đổi tần số như hình. Tốc độ truyền sóng trên dây là 60 m/s.</p><figure><img src=\"k11-bt/h/image131.png\" width=\"650\" height=\"653\" style=\"width:7.5cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure><p><b>a)</b> Lập luận để tìm biểu thức tổng quát của các tần số f mà tại đó trên dây có sóng dừng. Tính ba giá trị tần số nhỏ nhất.</p><p><b>b)</b> Khi bộ rung dao động với tần số 75 Hz, xác định số nút, số bụng và vị trí nút sóng thứ ba tính từ đầu P.</p>", "lc": [], "ds": [], "col": 0, "da": "a) - Dây hai đầu cố định: <span class=\"m\">L=\\dfrac{n\\lambda}{2}=\\dfrac{nv}{2f}</span> → f = <span class=\"m\">\\dfrac{nv}{2L}</span> = 25n (Hz), với n = 1, 2, 3,...", "lg": "<p>- Ba giá trị nhỏ nhất: f₁ = 25 Hz; f₂ = 50 Hz; f₃ = 75 Hz.</p><p>b) - Với f = 75 Hz → n = 3: trên dây có 3 bụng sóng và 4 nút sóng (kể cả hai đầu).</p><p>Vị trí nút sóng thứ 3: x= 0,8 m.</p>"}]}, "B15": {"ten": "Bài 15. Thực hành: Đo tốc độ truyền âm", "ch": "Chương II. Sóng", "dem": {"I": 6, "II": 2, "III": 0, "TL": 0}, "word": "k11-bt/word/Bai15_Thuc_hanh_do_toc_do_truyen_am.docx", "wordDa": "k11-bt/word/Bai15_Thuc_hanh_do_toc_do_truyen_am_Dap_an.docx", "wordCh": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai.docx", "wordChDa": "k11-bt/word/Chuong2_Song_Bai_tap_theo_bai_Dap_an.docx", "I": [{"than": "<p>Mục tiêu của bài thực hành đo tốc độ truyền âm</p>", "lc": [["A", "xác định tần số của nguồn âm."], ["B", "xác định tốc độ truyền âm trong không khí bằng dụng cụ thực hành."], ["C", "xác định cường độ âm của nguồn phát."], ["D", "xác định bước sóng của ánh sáng."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Hình bên là bộ thí nghiệm đo tốc độ truyền âm dụng cụ số (3) là</p><figure><img src=\"k11-bt/h/image132c0.png\" width=\"218\" height=\"299\" style=\"width:3.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [["A", "máy phát tần số phát ra tín hiệu có dạng sin."], ["B", "loa phát ra sóng âm."], ["C", "ống trụ làm bằng thủy tinh trong suất."], ["D", "pittông làm bằng thép bọc nhựa."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Trong thí nghiệm đo tốc độ truyền âm trong không khí, dụng cụ nào sau đây tạo ra tín hiệu âm</p>", "lc": [["A", "loa."], ["B", "pittông làm bằng thép bọc nhựa."], ["C", "máy phát tần số phát ra tín hiệu có dạng sin."], ["D", "ống trụ làm bằng thủy tinh trong suất."]], "ds": [], "col": 1, "da": "A", "lg": ""}, {"than": "<p>Trong quá trình thực hành đo tốc độ truyền âm, để giảm sai số khi xác định bước sóng, cách làm nào sau đây là phù hợp nhất</p>", "lc": [["A", "chỉ đo khoảng cách giữa hai vị trí cực đại liên tiếp."], ["B", "đo nhiều lần khoảng cách giữa hai vị trí cực đại liên tiếp."], ["C", "chỉ thực hiện phép đo một lần."], ["D", "chọn khoảng cách đo càng nhỏ càng tốt."]], "ds": [], "col": 1, "da": "B", "lg": ""}, {"than": "<p>Trong một môi trường không đổi, nếu tăng tần số của nguồn âm thì tốc độ truyền âm sẽ</p>", "lc": [["A", "tăng."], ["B", "giảm."], ["C", "không đổi."], ["D", "bằng không."]], "ds": [], "col": 4, "da": "C", "lg": ""}, {"than": "<p>Trong thí nghiệm đo tốc độ truyền âm bằng ống cộng hưởng, gọi chiều cao của cột không khí trong ống là <span class=\"m\">l_{1}</span> và <span class=\"m\">l_{2}</span> khi tai ta nghe liên tiếp hai lần âm to nhất. Liên hệ giữa bước sóng λ và <span class=\"m\">l_{1}</span>, <span class=\"m\">l_{2}</span> là</p>", "lc": [["A", "<span class=\"m\">l_{2}</span> - <span class=\"m\">l_{1}</span> = <span class=\"m\">\\dfrac{}{2}</span>."], ["B", "<span class=\"m\">l_{2}</span> - <span class=\"m\">l_{1}</span> = <span class=\"m\">\\dfrac{}{4}</span>."], ["C", "<span class=\"m\">l_{2}</span> - <span class=\"m\">l_{1}</span> =."], ["D", "<span class=\"m\">l_{2}</span> - <span class=\"m\">l_{1}</span> = 2."]], "ds": [], "col": 4, "da": "A", "lg": ""}], "II": [{"than": "<p>Trong thí nghiệm đo tốc độ truyền âm bằng bộ dụng cụ thực hành như hình. Phát biểu sau đây là đúng hay sai?</p><figure><img src=\"k11-bt/h/image132c0.png\" width=\"218\" height=\"299\" style=\"width:3.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Âm truyền trong không khí có dạng hình sin."], ["b", "Để xác định tốc độ truyền âm, cần xác định được thời gian âm truyền từ nguồn đến máy thu."], ["c", "Đo tốc độ truyền âm là phép đo gián tiếp."], ["d", "Đo tốc độ truyền âm là một trong những ứng dụng của hiện tượng sóng dừng"]], "col": 0, "da": "Đ S Đ Đ", "lg": ""}, {"than": "<p>Bộ thí nghiệm đo tốc độ truyền âm bằng bộ dụng cụ thực hành như hình bên. Phát biểu sau đây là đúng hay sai?</p><figure><img src=\"k11-bt/h/image132c0.png\" width=\"218\" height=\"299\" style=\"width:3.8cm\" alt=\"Hình minh hoạ\" loading=\"lazy\"></figure>", "lc": [], "ds": [["a", "Dụng cụ số (2) là pit-tông làm bằng thép bọc nhựa."], ["b", "Sóng dừng xảy ra trong cột không khí phía dưới pittông."], ["c", "Việc đo nhiều lần rồi lấy giá trị trung bình làm góp phần giảm ảnh hưởng sai số ngẫu nhiên."], ["d", "Nếu tăng tần số của máy phát tần số thì tốc độ truyền âm trong không khí tăng."]], "col": 0, "da": "Đ Đ Đ S", "lg": ""}], "III": [], "TL": []}};
